// Üretilen dosya: tool/ozgun/uret.py. Toplum ve Sosyal Bilimler · İletişim bilimleri, medya kuramları ve medya okuryazarlığı (gündem belirleme, suskunluk sarmalı, çerçeveleme, yankı odası, dezenformasyon) (zor).
const ozSocialscience16Zor = <(String, String, List<String>, String)>[
  ('Frank Dance tarafından önerilen sarmal (helisel) iletişim modelinin dairesel modellere yönelttiği en temel eleştiri aşağıdakilerden hangisidir?', 'Dairesel modellerin iletişimi başladığı noktaya aynen geri dönen kapalı bir süreç gibi göstermesi', ['Dairesel modellerin kitle iletişim araçlarını kişilerarası sohbetten daha üstün tutması', 'Sözsüz iletişim kanallarının teknik gürültüden hiç etkilenmediğini varsayması', 'Alıcının yaş ve eğitim düzeyini kodlama sürecinin dışında bırakması'], 'Dance\'e göre iletişim asla tam olarak başladığı noktaya dönmez; her etkileşim önceki deneyimlerin üzerine inşa edilerek yukarı doğru genişleyen bir sarmal gibi ilerler.'),
  ('David Berlo\'nun 1960 tarihli SMCR (Kaynak-İleti-Kanal-Alıcı) modelinde \'kanal\' öğesi hangi unsurlarla eşleştirilerek çözümlenir?', 'Görme, işitme, dokunma, koklama ve tatma duyuları', ['Telgraf, radyo, sinema, televizyon ve gazete işletmeleri', 'Aile, okul, sendika, siyasal parti ve meslek odaları', 'Anayasa, yayın ilkeleri, sansür kurulları ve telif yasaları'], 'Berlo SMCR modelinde mesajın alıcıya ulaştığı kanalları insanın beş temel duyusu (görme, işitme, dokunma, tatma, koklama) üzerinden yapılandırmıştır.'),
  ('Theodore Newcomb\'un 1953\'te geliştirdiği üçgen biçimli ABX modelinin temel varsayımı aşağıdakilerden hangisidir?', 'İki bireyin ortak bir nesne veya konuya ilişkin tutumlarında simetri ve denge kurma eğilimi taşıması', ['Radyo yayınlarının kırsal kesimdeki okuryazar olmayan kitleyi doğrudan hipnotize etmesi', 'Büyük medya holdinglerinin reklamveren baskısıyla muhalif haberleri tamamen engellemesi', 'Bireylerin yalnızca kendi meslek gruplarındaki yazılı bültenlere güven duyması'], 'Newcomb\'un ABX modelinde A ve B kişileri birbirleriyle ve X konusuyla ilişki içindedir; X hakkındaki tutum uyuşmazlığı gerilim yaratır ve iletişimi denge arayışına yöneltir.'),
  ('Shannon-Weaver modelinde bir mesajın önceden tahmin edilebilirlik düzeyinin düşmesi ve belirsizliğin en üst noktaya çıkması hangi terimle karşılanır?', 'Entropi', ['Artıklık', 'Yöndeşme', 'Eşzamanlılık'], 'Bilgi kuramında entropi, mesajdaki belirsizlik ve düzensizlik ölçüsüdür; artıklık (tekrar) ise gürültüye karşı anlam kaybını önlemek için eklenen öngörülebilir unsurlardır.'),
  ('Havacılık telsiz haberleşmesinde harflerin \'Alfa, Bravo, Charlie\' şeklinde fonetik kodlarla telaffuz edilmesi bilgi kuramındaki hangi ilkenin pratik uygulamasıdır?', 'Gürültünün yol açabileceği yanlış anlamaları azaltmak için artıklığı (redundancy) yükseltme', ['Kanal kapasitesini daraltarak mesajın şifresini üçüncü kişilerden gizleme', 'Geri bildirim süresini uzatarak hiyerarşik otoriteyi pekiştirme', 'Sözsüz iletişim ipuçlarını sesli iletişimin önüne geçirme'], 'Shannon-Weaver kuramında artıklık, parazitli kanallarda sinyalin bozulma riskine karşı ek ipuçları ve tekrarlar kullanarak iletinin doğru çözülmesini güvenceye alır.'),
  ('Bruce Westley ve Malcolm MacLean\'in 1957\'de sundukları iletişim modelini kişilerarası modellerden ayıran ve kitle iletişimine uyarlayan kritik yenilik hangisidir?', 'Olaylar (X) ile izleyici (B) arasına haber seçip aktaran aracı kurumu (C - eşik bekçisi) yerleştirmesi', ['İletişim sürecinden kaynak ve alıcı kavramlarını bütünüyle çıkarması', 'Gürültünün yalnızca basılı gazetelerde ortaya çıktığını ileri sürmesi', 'İzleyicinin medya kuruluşlarına doğrudan yayın lisans ücreti ödediğini varsayması'], 'Westley-MacLean modeli, bireyin doğrudan gözlemleyemediği geniş çevre olaylarını seçip işleyerek kitleye aktaran medya profesyonellerini (C) modele dahil etmiştir.'),
  ('Paul Ekman ve Wallace Friesen\'in beden hareketleri sınıflandırmasında, konuşma olmadan da tek başına belirli bir sözcüğün yerini tutabilen \'başparmağı yukarı kaldırma\' veya \'zafer işareti yapma\' gibi hareketlere ne ad verilir?', 'Amblem', ['Uyarlayıcı', 'Düzenleyici', 'Duygu gösterimi'], 'Amblemler, belirli bir kültür içinde herkesçe bilinen net bir sözel karşılığı olan ve sözcük kullanmadan doğrudan mesaj ileten bilinçli jestlerdir.'),
  ('Göz teması kurma süresini, bakış kaçırmayı, göz kırpma sıklığını ve gözbebeği büyümesinin iletişimsel anlamlarını inceleyen sözsüz iletişim alt dalı aşağıdakilerden hangisidir?', 'Okuletik', ['Haptik', 'Kronemik', 'Vokalik'], 'Okuletik (oculesics), göz hareketlerinin ve bakış davranışlarının kültürden kültüre değişen ilgi, dürüstlük, saygı veya tehdit mesajlarını araştırır.'),
  ('George Gerbner\'in 1956 tarihli genel iletişim modelini Shannon-Weaver çizgisinden ayıran en önemli kuramsal vurgu nedir?', 'Gerçeklikteki bir olayın algılanma ve seçilme biçimini merkeze alarak iletişimi anlam üretimiyle ilişkilendirmesi', ['İletişim sürecini yalnızca bakır kablolardaki elektrik voltajı değişimleriyle sınırlandırması', 'İzleyicinin kitle iletişim araçlarına anında telefonla bağlanmasını zorunlu sayması', 'Sözlü iletişimin sanayi toplumlarında tamamen ortadan kalkacağını öne sürmesi'], 'Gerbner modeli iletişimi \'birisinin bir olayı algılaması ve tepki vermesi...\' dizgesiyle kurgulayarak algısal seçicilik ve temsil boyutunu matematiksel aktarımın önüne koymuştur.'),
  ('Charles Morris\'in göstergebilimi üç alt dala ayırdığı modelde, göstergelerin birbirleriyle olan biçimsel ve dizgesel kurallarını inceleyen boyut hangisidir?', 'Sentaktik (sözdizim)', ['Semantik (anlambilim)', 'Pragmatik (edimbilim)', 'Etimoloji (kökenbilim)'], 'Morris\'e göre sentaktik göstergelerin diğer göstergelerle yapısal ilişkisini, semantik göstergelerin nesnelerle anlam ilişkisini, pragmatik ise göstergelerin kullanıcılarla pratik ilişkisini inceler.'),
  ('Bir televizyon tartışmasında katılımcının karşı tarafın sözünü bitirmesini teşvik etmek için hafifçe başını sallaması veya söz almak istediğini belli etmek için işaret parmağını kaldırması hangi kinesik işlevdir?', 'Düzenleyici', ['Amblem', 'Uyarlayıcı', 'Simülakr'], 'Düzenleyiciler (regulators), karşılıklı konuşmada söz sırasının kimde olduğunu, konuşmanın hızlanmasını ya da sonlanmasını denetleyen sözsüz işaretlerdir.'),
  ('Sözlü kültürden yazılı ve matbaa kültürüne geçişin insan bilincini işitsel-bütüncül algıdan görsel-çizgisel ve analitik düşünceye dönüştürdüğünü savunan iletişim düşünürü kimdir?', 'Walter J. Ong', ['Paul Lazarsfeld', 'Carl Hovland', 'Kurt Lewin'], 'Walter J. Ong, \'Sözlü ve Yazılı Kültür: Sözün Teknolojileşmesi\' adlı yapıtında yazının ve matbaanın insanın bellek ve düşünme yapısını kökten yeniden örgütlediğini ortaya koymuştur.'),
  ('John Fiske\'in iletişim çalışmalarını iki ana ekole ayırdığı sınıflandırmada, iletişimi \'iletilerin aktarımı\' yerine \'anlamların üretimi ve değişimi\' olarak gören yaklaşım hangisidir?', 'Göstergebilimsel okul', ['Süreç okulu', 'Sibernetik mühendislik okulu', 'Davranışçı uyaran-tepki okulu'], 'Fiske\'e göre Süreç Okulu (Shannon-Weaver, Lasswell) iletinin verimli aktarımına odaklanırken, Göstergebilimsel Okul (Saussure, Peirce, Barthes) metin ile kültürün etkileşiminden doğan anlam üretimine odaklanır.'),
  ('Fiske\'in \'Süreç Okulu\' ile \'Göstergebilimsel Okul\' karşılaştırmasında, iletişimde yaşanan bir anlaşmazlık bu iki okul tarafından sırasıyla nasıl yorumlanır?', 'Süreç okulunda kanal/kodlama arızası, göstergebilimsel okulda ise kültürel farktan doğan doğal çokanlamlılık olarak', ['Süreç okulunda sanatsal zenginlik, göstergebilimsel okulda ise kablo kopukluğu olarak', 'Her iki okulda da alıcının biyolojik zekâ yetersizliği olarak', 'Süreç okulunda ideolojik direniş, göstergebilimsel okulda ise akustik yankı olarak'], 'Süreç okulu niyet edilen anlamın ulaşmamasını \'iletişim başarısızlığı/gürültü\' sayarken, göstergebilimsel okul farklı okuma biçimlerini sosyokültürel konum farklılıklarının doğal sonucu görür.'),
  ('Roland Barthes\'ın Paris Match dergisinin kapağında Fransız bayrağını selamlayan siyahi genç asker fotoğrafını çözümlerken ulaştığı \'Fransa ayrımcılık yapmayan büyük bir imparatorluktur\' mesajı hangi kavramla açıklanır?', 'Mit', ['Salt düzanlam', 'Akustik sinyal', 'Fizyolojik refleks'], 'Barthes\'a göre mit, tarihsel ve politik olarak üretilmiş egemen değerleri sanki doğalmış ve sorgulanamaz bir gerçekmiş gibi sunan ikinci düzey göstergebilimsel dizgedir.'),
  ('Kanadalı iktisatçı ve iletişim tarihçisi Harold Innis\'e göre kil tablet, taş yazıt ve parşömen gibi ağır ve dayanıklı iletişim araçları imparatorluklarda nasıl bir eğilim yaratır?', 'Zaman yanlısı (time-biased) olup dini geleneklerin ve kuşaklararası sürekliliğin korunmasını destekler', ['Mekân yanlısı olup uzak eyaletlerin hızlıca askeri denetim altına alınmasını kolaylaştırır', 'Yazılı hukuku ortadan kaldırarak anlık dedikodu ağlarını güçlendirir', 'Ticari muhasebe kayıtlarının birkaç gün içinde kendiliğinden silinmesine yol açar'], 'Innis iletişim araçlarını zaman yanlısı (taş, kil gibi kalıcı fakat taşınması zor) ve mekân yanlısı (papirüs, kâğıt gibi hafif, geniş coğrafyalarda bürokratik yönetimi kolaylaştıran) olarak ikiye ayırmıştır.'),
  ('Harold Innis\'in iletişim tarihi kuramında papirüs ve kâğıt gibi hafif, kolay taşınabilir medya ortamlarının toplumsal örgütlenme üzerindeki başat etkisi nedir?', 'Mekân yanlısı (space-biased) nitelikleriyle geniş coğrafyalarda merkezi idare ve ticareti mümkün kılması', ['Bilginin yalnızca tapınak rahiplerinin sözlü ezberinde kalmasını sağlaması', 'Uzak bölgeler arasındaki haberleşmeyi tamamen olanaksız hâle getirmesi', 'Merkezi bürokrasiyi zayıflatarak kapalı köy ekonomisine dönüşü hızlandırması'], 'Hafif ve hızlı çoğaltılan araçlar mekân engelini aşarak uzak topraklara emir ve yasa ulaştırılmasını, dolayısıyla geniş imparatorluk ve devlet yönetimini destekler.'),
  ('Watzlawick\'in iletişim aksiyomlarına göre her iletinin sahip olduğu iki temel düzey aşağıdakilerden hangisinde doğru verilmiştir?', 'Bilgi aktaran \'içerik\' düzeyi ve mesajın nasıl anlaşılacağını belirleyen \'ilişki\' düzeyi', ['Maliyeti hesaplayan \'ekonomik\' düzey ve cezayı belirleyen \'hukuki\' düzey', 'Yalnızca geçmişi anlatan \'tarihsel\' düzey ve geleceği tahmin eden \'kehanet\' düzeyi', 'Kablolu iletimi sağlayan \'metalik\' düzey ve kablosuz iletimi sağlayan \'optik\' düzey'], 'Palo Alto yaklaşımına göre her iletişimde bir ne söylendiği (içerik/rapor), bir de tarafların birbirini nasıl konumlandırdığını gösteren ses tonu ve bağlam (ilişki/komut) boyutu vardır.'),
  ('Charles Hockett\'in insan dilini hayvan iletişim sistemlerinden ayıran tasarım özellikleri arasında yer alan \'yer ve zamandan bağımsızlık\' (displacement) ilkesi neyi ifade eder?', 'İnsanın o an orada bulunmayan, geçmişte kalmış, gelecekteki veya hayalî şeylerden söz edebilmesini', ['Konuşma seslerinin yalnızca açık havada ve gündüz saatlerinde yayılabilmesini', 'Her sözcüğün telaffuz edildiği coğrafi bölgeye göre fiziksel ağırlığının değişmesini', 'İletişimin gerçekleşmesi için tarafların mutlaka aynı odada bulunması zorunluluğunu'], 'Hayvan sinyalleri çoğunlukla anlık tehlike veya besin kaynağına bağlıyken insan dili yüzyıllar öncesini, uzak galaksileri ya da kurgusal varlıkları anlatabilme kapasitesine sahiptir.'),
  ('İnsan dilinde sınırlı sayıdaki anlamsız ses biriminin (harf/fonem) farklı dizilişlerle bir araya gelerek binlerce anlamlı sözcük üretmesine dilbilimde ne ad verilir?', 'Çift eklemlilik', ['Tek yönlü nedensellik', 'Biyolojik yansıma', 'Durağan şifreleme'], 'André Martinet ve Hockett tarafından vurgulanan çift eklemlilik, az sayıda sesbirimle (ör. k-a-l-e-m / k-e-l-a-m / e-m-l-a-k) sınırsız anlamlı birim üretebilme ekonomisidir.'),
  ('Albert Mehrabian\'ın duyguların ve tutumların iletimine dair yaptığı klasik araştırmaların temel bulgusu sıklıkla nasıl yanlış genellenmektedir?', 'Yalnızca tutarsız duygu/tutum ifadeleri için geçerli olan oranların tüm teknik ve bilimsel konuşmalara da uygulanmasıyla', ['Sözsüz iletişimin insanlar arasında hiçbir zaman kullanılmadığının iddia edilmesiyle', 'Yazılı mektupların yüz yüze konuşmadan daha yüksek ses tonuna sahip olduğunun sanılmasıyla', 'Göz temasının yalnızca karanlık ortamlarda anlam ürettiğinin öne sürülmesiyle'], 'Mehrabian %7 söz, %38 ses tonu, %55 yüz ifadesi formülünü yalnızca bir kişinin hoşlanma/hoşlanmama duygusunu söz ve tonu çelişerek ifade ettiği dar bağlam için bulmuştur; bilimsel ders anlatımına genellenemez.'),
  ('Göstergebilimde \'Beyaz Saray dün akşam açıklama yaptı\' veya \'Ankara bu öneriye sıcak bakmıyor\' cümlelerinde mekân adının yöneticilerin yerine kullanılması hangi anlam aktarım düzeneğidir?', 'Düzdeğişmece', ['Fonetik benzeşme', 'Düzanlamsal daralma', 'Fiziksel parazit'], 'Roman Jakobson ve göstergebilimcilerin vurguladığı metonimi (düzdeğişmece/ad aktarması), bir kavramı onunla bitişik veya ilişkili başka bir unsurla (bina, başkent) temsil etmektir.'),
  ('Yüz ifadelerinin mutluluk, öfke, korku, şaşkınlık, tiksinti ve üzüntü gibi temel duygularda farklı kıtalardaki toplumlarda benzer biçimde tanınmasını ancak bu duyguları dışavurma sıklığının kültürce denetlenmesini Paul Ekman hangi kavramla açıklar?', 'Gösterim kuralları', ['Suskunluk sarmalı', 'Algoritmik filtreleme', 'Mekanik entropi'], 'Ekman\'a göre temel yüz ifadelerinin biyolojik kökeni evrenseldir; ancak kimin, nerede, ne ölçüde ağlayabileceği ya da öfkesini gizleyeceği kültürel gösterim kurallarıyla öğrenilir.'),
  ('Dilbilimci Karl Bühler\'in \'Organon Modeli\'nde dilsel göstergenin eşzamanlı olarak ilişkili olduğu üç temel kutup hangileridir?', 'Gönderici (anlatım), alıcı (çağrı) ve nesneler/olgular', ['Matbaa, dağıtım şirketi ve gazete bayisi', 'Bilinç, bilinçöncesi ve bilinçdışı', 'Yasama, yürütme ve yargı organları'], 'Bühler 1934 tarihli Organon modelinde dili bir araç olarak ele almış; konuşucunun iç dünyasını dışavurma (anlatım), dinleyiciyi yönlendirme (çağrı) ve dünyayı betimleme (temsil) işlevlerini tanımlamıştır.'),
  ('Bir konuşmada dinleyicinin \'Hı-hı, anlıyorum, evet\' gibi kısa seslerle konuşmacıyı takip ettiğini belli etmesi iletişim çözümlemelerinde nasıl adlandırılır?', 'Arka kanal (back-channel) geri bildirim ipuçları', ['Söz sırasını zorla ele geçirme müdahalesi', 'Semantik kod bozumu', 'Kamusal propaganda tekniği'], 'Dinleyicinin konuşmacının sözünü kesmeden dinlemeye devam ettiğini ve mesajı aldığını gösteren kısa vokal ya da baş sallama tepkileri arka kanal sinyalleridir.'),
  ('İletişim kuramlarında \'kanal\' (channel) ile \'araç/ortam\' (medium) kavramları arasındaki ince ayrımı en doğru belirten seçenek hangisidir?', 'Kanal sinyali taşıyan fiziksel/duyusal yol iken araç bu sinyali kurumsal ve teknik biçime sokan iletişim ortamıdır', ['Kanal yalnızca yazılı metinler için, araç ise yalnızca sözsüz mimikler için kullanılır', 'Kanal izleyici kitlesinin yaş ortalamasını, araç ise mesajın harf sayısını gösterir', 'Kanal geri bildirimi yasaklarken araç geri bildirimi zorunlu kılar'], 'Ses dalgaları, ışık veya radyo frekansı iletiyi taşıyan fiziksel/duyusal kanalken; radyo, televizyon, kitap ya da telefon bu kodları örgütleyen teknik/kültürel araçtır (medium).'),
  ('James Grunig ve Todd Hunt\'ın dört halkla ilişkiler modelinden hangisi araştırmaya dayanır, karşılıklı anlayışı esas alır ve hem kurumun hem de hedef kitlenin tutumlarında uzlaşmacı değişimi kabul eder?', 'İki yönlü simetrik model', ['Basın ajanslığı ve tanıtım modeli', 'Kamuyu bilgilendirme modeli', 'İki yönlü asimetrik model'], 'Grunig\'e göre en etik ve çağdaş halkla ilişkiler yaklaşımı olan iki yönlü simetrik model, tek taraflı ikna yerine diyalog ve karşılıklı uyumu merkeze koyar.'),
  ('Bilimsel anket ve odak grup araştırmalarını yalnızca hedef kitlenin zayıf noktalarını öğrenip onları kurumun istediği yönde ikna etmek amacıyla kullanan, kurumun kendi politikasını ise hiç değiştirmeyen model hangisidir?', 'İki yönlü asimetrik model', ['İki yönlü simetrik model', 'Kamuyu bilgilendirme modeli', 'Doğrudan sansür modeli'], 'Edward Bernays çizgisindeki iki yönlü asimetrik modelde geri bildirim toplanır fakat bu veri diyalog için değil, kamuoyunu kurum lehine yönlendirmek (asimetrik etki) için kullanılır.'),
  ('Gazeteci kökenli Ivy Lee\'nin öncülüğünü yaptığı, doğru ve olgusal bilgileri basın bültenleriyle kamuoyuna tek yönlü olarak aktarmayı ilke edinen halkla ilişkiler modeli hangisidir?', 'Kamuyu bilgilendirme modeli', ['Basın ajanslığı modeli', 'İki yönlü simetrik model', 'Gizli viral pazarlama modeli'], 'Ivy Lee\'nin 1906 İlkeler Bildirgesi ile şekillenen kamuyu bilgilendirme modeli, yalan söylememeyi ve basına doğru enformasyon sağlamayı savunan tek yönlü bir modeldir.'),
  ('Transaksiyonel Analiz\'e göre bir çalışanın yöneticisine \'Raporun üçüncü sayfasındaki grafik verilerini nereden temin edebilirim?\' diye Yetişkin benlik durumundan sorduğu soruya yöneticinin \'Her işi de bana mı soracaksınız, biraz gözünüzü açın!\' diyerek Eleştirel Ebeveyn\'den yanıt vermesi nasıl bir işlemdir?', 'Çapraz transaksiyon', ['Tamamlayıcı (paralel) transaksiyon', 'Simetrik empatik döngü', 'Yatay uzlaşmacı yansıtma'], 'Berne\'ün kuramında beklenen benlik durumundan farklı bir benlik durumundan yanıt geldiğinde iletişim çizgileri kesişir (çapraz transaksiyon) ve iletişimde kopukluk ya da çatışma doğar.'),
  ('Harold Leavitt\'in küçük gruplarda iletişim ağları üzerine yaptığı deneysel araştırmalara göre karmaşık ve yaratıcılık gerektiren sorunların çözümünde çalışan memnuniyetinin en yüksek olduğu ağ yapısı hangisidir?', 'Merkezi olmayan \'çember / tüm kanal\' ağı', ['Tek bir liderin merkezde durduğu katı \'tekerlek\' ağı', 'Bilginin yalnızca sırayla aktarıldığı dikey \'zincir\' ağı', 'Alt kademelerin birbiriyle hiç konuşamadığı \'Y\' ağı'], 'Leavitt deneylerinde tekerlek gibi merkezi ağlar basit rutin görevlerde hızlı olsa da karmaşık problemlerde ve grup üyelerinin moral/tatmin düzeyinde tüm-kanallı merkeziyetsiz ağlar çok daha başarılı çıkmıştır.'),
  ('Olumsuz bir tek özelliğinden ötürü bir çalışanın diğer tüm başarılı çalışmalarının da kusurlu görülmesi eğilimine algı psikolojisinde ve örgütsel iletişimde ne ad verilir?', 'Boynuz (ters hale / horn) etkisi', ['Pygmalion (beklenti) etkisi', 'Hawthorne gözlem etkisi', 'Zeigarnik bellek etkisi'], 'Hale etkisinin tam tersi olan boynuz (horn) etkisinde, kişinin tek bir kusuru veya hatası zihinde büyütülerek tüm karakteri ve performansı olumsuz etiketlenir.'),
  ('Jack Gibb\'in 1961\'de ortaya koyduğu \'Savunucu ve Destekleyici İletişim İklimleri\' araştırmasına göre aşağıdakilerden hangisi karşı tarafta savunmacılığı tetikleyen davranışlardan biridir?', 'Üstünlük taslama, yargılama ve gizli stratejiyle yönlendirme', ['Soruna odaklanma, empati kurma ve geçici/esnek dil kullanma', 'Eşitlikçi yaklaşma, betimleyici konuşma ve içtenlik sergileme', 'Farklı görüşleri dinlemeye açık olma ve ortak çözüm arama'], 'Gibb\'e göre değerlendirici/yargılayıcı dil, kontrol çabası, kurnaz strateji, kayıtsızlık, üstünlük ve kesinlik (dogmatizm) savunucu iklim yaratırken; betimleyicilik, problem yönelimi, içtenlik, empati, eşitlik ve esneklik destekleyici iklim kurar.'),
  ('William Timothy Coombs\'un \'Durumsal Kriz İletişimi Kuramı\'na (SCCT) göre kurumun krizdeki kusur ve sorumluluk düzeyi arttıkça iletişim stratejisi nasıl şekillenmelidir?', 'İnkâr ve küçümsemeden uzaklaşıp tam özür dileme ve mağduriyeti tazmin etme stratejilerine yönelmelidir', ['Kriz büyüdükçe basına yapılan açıklamaların sayısı sıfıra indirilmeli ve sosyal medya hesapları kapatılmalıdır', 'Kurumun kusuru kesinleştiğinde gazetecilere yönelik saldırgan suçlama kampanyaları artırılmalıdır', 'Sorumluluk yüksek olduğunda yalnızca rakip şirketlerin geçmişteki hatalarını hatırlatan ilanlar verilmelidir'], 'Coombs\'a göre krizin kuruma atfedilen sorumluluğu (kurban kümesi, kaza kümesi, önlenebilir/kasıtlı küme) yükseldikçe itibar kaybını sınırlamak için kabullenici, özür dileyici ve telafi edici tepkiler zorunlu hâle gelir.'),
  ('Kişilerarası ilişkilerde Irwin Altman ve Dalmas Taylor\'ın \'Sosyal Nüfuz (Derinleşme) Kuramı\'nda ilişkilerin yüzeysel tanışıklıktan mahrem paylaşımlara doğru ilerlemesi hangi metaforla açıklanır?', 'Soğan zarlarının dış katmanlarından merkeze doğru soyulması', ['Telgraf tellerinden geçen mors alfabesi sinyalleri', 'Şelaleden aşağıya doğru tek yönlü dökülen su kütleleri', 'Mıknatısın aynı kutuplarının birbirini hızla itmesi'], 'Sosyal nüfuz kuramı kişiliği çok katmanlı bir soğana benzetir; ilişki ilerledikçe hava durumu ve hobiler gibi dış katmanlardan korkular, değerler ve mahrem anılar gibi iç çekirdeğe doğru karşılıklı kendini açma gerçekleşir.'),
  ('Charles Berger ve Richard Calabrese\'nin \'Belirsizliğin Azaltılması Kuramı\'na göre birbirini hiç tanımayan iki insanın ilk karşılaşmada çok sayıda soru sormasının temel güdüsü nedir?', 'Karşı tarafın davranışlarını öngörebilmek ve açıklamakta duyulan bilişsel kaygıyı düşürmek', ['Muhatabın gizli banka hesap şifrelerini ele geçirerek haksız kazanç sağlamak', 'Sözsüz iletişim kanallarını tamamen devre dışı bırakarak yalnızca yazılı sözleşme imzalamak', 'Kitle iletişim araçlarının gündem belirleme gücünü bireysel sohbete taşımak'], 'Kurama göre yabancılarla ilk etkileşimde belirsizlik yüksektir; pasif gözlem, aktif araştırma ve etkileşimsel soru sorma stratejileriyle öngörülebilirlik artırılmaya çalışılır.'),
  ('Üstün Dökmen\'in geliştirdiği \'Aşamalı Empati Sınıflandırması\'nda en yüzeysel basamaktan en derin basamağa doğru sıralanan üç düzey hangileridir?', 'Onlar basamağı, ben basamağı ve sen basamağı', ['Geçmiş basamağı, bugün basamağı ve gelecek basamağı', 'Fiziksel basamak, biyolojik basamak ve kimyasal basamak', 'Yerel basamak, ulusal basamak ve küresel basamak'], 'Dökmen\'e göre \'Onlar\' basamağında toplumun ne diyeceği söylenir (atasözü vb.), \'Ben\' basamağında dinleyici konuyu kendine çeker, en üstteki \'Sen\' basamağında ise doğrudan sorun sahibinin duygu ve düşüncesine odaklanılır.'),
  ('Paul Grice\'ın \'İşbirliği İlkesi\' ve konuşma maksimlerine göre bir soruya gerekenden ne daha az ne de konu dışına taşacak kadar aşırı fazla bilgi vererek yanıtlamak hangi ilkeyle ilgilidir?', 'Nicelik ilkesi', ['Nitelik ilkesi', 'Bağıntı ilkesi', 'Tarz ilkesi'], 'Grice\'ın dört konuşma maksiminde Nicelik gerektiği kadar bilgi vermeyi, Nitelik kanıtsız/yalan söylememeyi, Bağıntı konuyla ilgili kalmayı, Tarz ise muğlaklıktan kaçınıp açık olmayı buyurur.'),
  ('Grice\'ın konuşma ilkelerine göre doğru olmadığını bildiği bir iddiayı veya yeterli kanıtı bulunmayan bir dedikoduyu gerçekmiş gibi anlatan konuşmacı hangi maksimi ihlal etmiştir?', 'Nitelik maksimini', ['Nicelik maksimini', 'Kronemik maksimini', 'Proksemik maksimini'], 'Nitelik (quality) maksimi dürüstlüğü ve doğruluk paydasını korur; yanlış olduğuna inanılan ya da dayanağı olmayan sözlerden kaçınmayı gerektirir.'),
  ('Bir yöneticinin yeni başlayan bir stajyerden çok yüksek başarı beklediğini hissettirmesi sonucunda stajyerin özgüven kazanarak gerçekten de üstün performans sergilemesi iletişim ve eğitim psikolojisinde hangi kavramla anılır?', 'Pygmalion (beklenti) etkisi', ['Boynuz (horn) yanılgısı', 'Bilişsel tembellik etkisi', 'Üçüncü kişi etkisi'], 'Robert Rosenthal ve Lenore Jacobson\'ın ortaya koyduğu Pygmalion etkisi, yüksek beklentilerin sözlü/sözsüz destekleyici ipuçlarıyla karşı tarafa geçerek başarıyı artıran kendini gerçekleştiren kehanete dönüşmesidir.'),
  ('Halkla ilişkiler kampanyası planlanırken kullanılan dört aşamalı klasik \'RACE\' (John Marston) modelinin basamakları sırasıyla nelerdir?', 'Araştırma, Eylem planlama, İletişim uygulama ve Değerlendirme', ['Reklam, Arşivleme, Sansürleme ve Endeksleme', 'Raporlama, Atama, Cezalandırma ve Erteleme', 'Rekabet, Ayrıştırma, Çoğaltma ve Egemenlik'], 'Marston\'ın RACE formülü; Research (Araştırma), Action/planning (Eylem ve planlama), Communication (İletişim/uygulama) ve Evaluation (Değerlendirme/ölçümleme) adımlarından oluşur.'),
  ('Richard Petty ve John Cacioppo\'nun \'Ayrıntılandırma Olasılığı Modeli\'ne (ELM) göre alıcının konuyla ilgisi ve motivasyonu çok yüksek olduğunda ikna süreci hangi yoldan gerçekleşir?', 'Kanıtların gücünü ve mantıksal tutarlılığı dikkatle tartan \'merkezi yol\' üzerinden', ['Yalnızca konuşmacının fiziksel çekiciliğine ve arka plan müziğine bakan \'çevresel yol\' üzerinden', 'Hiçbir bilinçli düşünme gerektirmeyen koşulsuz biyolojik refleks üzerinden', 'Mesajın içeriğini tamamen reddeden otomatik savunma duvarı üzerinden'], 'ELM kuramında yüksek ilgi ve bilişsel kapasite varsa birey argüman kalitesini inceleyen \'merkezi yol\'u kullanır; ilgi düşükse ünlü kullanımı veya ambalaj rengi gibi yüzeysel ipuçlarına dayalı \'çevresel yol\' devreye girer.'),
  ('Grup içi karar alma süreçlerinde Irving Janis\'in tanımladığı \'Grup Düşüncesi\' (Groupthink) sendromunun ortaya çıkmasının en tehlikeli sonucu aşağıdakilerden hangisidir?', 'Grup uyumunu bozmama kaygısıyla eleştirel itirazların bastırılması ve hatalı kararların oybirliğiyle alınması', ['Her üyenin farklı seçenekleri özgürce tartışması nedeniyle karar kalitesinin yükselmesi', 'Grup dışındaki bağımsız uzmanların görüşlerine gereğinden fazla zaman ayrılması', 'Toplantı tutanaklarının yazılı olarak tüm katılımcılara şeffaf biçimde dağıtılması'], 'Aşırı birbirine kenetlenmiş ve dış dünyaya kapalı gruplarda üyeler dışlanma korkusuyla şüphelerini gizler; bu sahte uzlaşı (groupthink) gerçeklikten kopuk felaket kararlara yol açabilir.'),
  ('Müzakere ve ikna araştırmalarında önce karşı tarafın kesinlikle reddedeceği çok büyük bir talepte bulunup hemen ardından asıl istenen daha makul talebi sunarak kabul şansını artırma tekniğine ne ad verilir?', 'Yüzüne kapıyı çarpma (reddet-sonra-geri-çekil) tekniği', ['Kapıya ayak koyma (küçükten büyüğe) tekniği', 'Etkin empatik aynalama tekniği', 'Açık pencere kendini açma tekniği'], 'Robert Cialdini\'nin incelediği \'door-in-the-face\' tekniğinde ilk aşırı talep reddedildikten sonra sunulan küçük talep karşı tarafta karşılıklı taviz verme normunu harekete geçirir.'),
  ('Önce reddedilmesi zor çok küçük bir ricayı (\'Çevre koruma dilekçemize bir imza atar mısınız?\') kabul ettirip birkaç gün sonra aynı kişiden daha büyük bir istekte (\'Hafta sonu fidan dikme etkinliğimizde üç saat gönüllü çalışır mısınız?\') bulunma ikna stratejisi hangisidir?', 'Kapıya ayak koyma (foot-in-the-door) tekniği', ['Yüzüne kapıyı çarpma tekniği', 'Korku çekiciliğiyle yıldırma tekniği', 'Savunmacı soyutlama tekniği'], 'Kapıya ayak koyma tekniği, bireyin küçük bir eylemi kabul ettikten sonra kendi öz-algısıyla tutarlı kalmak adına aynı doğrultudaki daha büyük talebe \'evet\' deme olasılığının artmasına dayanır.'),
  ('Howard Giles\'ın \'İletişim Uyarlama Kuramı\'na (Communication Accommodation Theory) göre iki kişinin sohbet sırasında farkında olmadan birbirinin konuşma hızına, ses tonuna ve sözcük seçimlerine yaklaşması hangi kavramla açıklanır?', 'Yakınsama (convergence)', ['Iraksama (divergence)', 'Simgesel imha', 'Mekanik gürültü'], 'Giles\'a göre sosyal onay kazanmak ve yakınlık kurmak isteyen bireyler dilsel ve sözsüz tarzlarını birbirine benzetir (yakınsama); kimlik farkını ve mesafeyi vurgulamak istediklerinde ise farklılaştırırlar (ıraksama).'),
  ('Kişilerarası çatışmalarda geçmişte çözülememiş on farklı eski kırgınlığın tek bir küçük tartışma anında biriktirilip birdenbire ortaya dökülmesi literatürde hangi mecazla anlatılır?', 'Çuval doldurma / silah depolama', ['Zihinsel haritalama', 'Bilişsel sadeleştirme', 'İki aşamalı akış'], 'Zamanında \'ben dili\' ile konuşulmayıp içe atılan kızgınlıkların bir çuvalda biriktirilip alakasız küçük bir kıvılcımda hepsinin birden boşaltılması (gunnysacking) yapıcı çözümü imkânsızlaştırır.'),
  ('William Schutz\'un \'Kişilerarası İlişkilerin Temel Yönelimi\' (FIRO) kuramına göre insanların gruplara katılırken ve iletişim kurarken doyurmaya çalıştıkları üç temel kişilerarası ihtiyaç hangileridir?', 'Dahil olma (aidiyet), kontrol (etki) ve sevgi/yakınlık', ['Uyumak, beslenmek ve barınmak', 'Vergi ödemek, oy kullanmak ve askerlik yapmak', 'Kodlamak, arşivlemek ve sansürlemek'], 'Schutz\'un 1958 tarihli FIRO kuramı kişilerarası etkileşimi; bir gruba ait olup tanınma (inclusion), karar süreçlerinde yetki ve düzen kurma (control) ile duygusal sıcaklık/yakınlık (affection) ihtiyaçlarıyla açıklar.'),
  ('Stella Ting-Toomey\'nin \'Yüz Müzakeresi Kuramı\'na (Face-Negotiation Theory) göre çatışma anında bireyci kültürler ile toplulukçu (kolektivist) kültürler arasındaki temel iletişim farkı nedir?', 'Bireyci kültürler kendi itibarını (öz-yüz) korumaya ve doğrudan yüzleşmeye, toplulukçu kültürler ise karşı tarafın itibarını (öteki-yüz) gözetmeye ve dolaylı uyuma yönelir', ['Bireyci kültürler çatışmalarda her zaman tamamen sessiz kalırken toplulukçu kültürler yalnızca yazılı mahkeme dilekçesiyle iletişim kurar', 'Her iki kültür tipinde de insanların toplumsal saygınlık ve itibar kaygısı iletişim sürecinde hiçbir rol oynamaz', 'Toplulukçu kültürlerde sözsüz iletişim hiç kullanılmazken bireyci kültürlerde sözlü iletişim yasaklanmıştır'], 'Ting-Toomey, Erving Goffman\'ın \'yüz/itibar\' kavramını kültürlerarası çatışmaya uyarlamış; kolektivist kültürlerin ilişkisel uyumu ve karşı tarafı mahcup etmemeyi öncelediğini göstermiştir.'),
  ('1950 yılında "Bay Gates" takma adlı bir telgraf editörünün haber seçme ve eleme kararlarını inceleyerek eşik bekçiliği kavramını gazetecilik literatürüne taşıyan araştırmacı kimdir?', 'David Manning White', ['Elisabeth Noelle-Neumann', 'George Gerbner', 'Elihu Katz'], 'David Manning White, telgraf editörü "Mr. Gates"in ajans haberlerinin büyük kısmını öznel ve mesleki ölçütlerle nasıl elediğini ampirik olarak incelemiştir.'),
  ('Suskunluk Sarmalı kuramında bireylerin anketlere bakmaksızın çevrelerindeki baskın görüşün yönünü ve gücünü sezgisel olarak ölçebilme yetisine ne ad verilir?', 'Yarı-istatistiksel duyu', ['Seçici algılama mekanizması', 'Bilişsel kestirme eğilimi', 'Sembolik etkileşim yetisi'], 'Noelle-Neumann\'a göre insanlar "yarı-istatistiksel duyu organı" (quasi-statistical sense) sayesinde hangi görüşün yükselişte veya düşüşte olduğunu sürekli gözlemler.'),
  ('Ekme Kuramı araştırmalarında, kendi gerçek yaşam deneyimleri televizyondaki şiddet temsilleriyle örtüşen izleyicilerde medya etkisinin iki kat güçlü görülmesine ne ad verilir?', 'Rezonans (Yankılanım)', ['Anaakımlaştırma (Mainstreaming)', 'Öncül hazırlama (Priming)', 'Bilişsel çerçeveleme'], 'Gerbner\'e göre yüksek suç oranlı mahallelerde yaşayan izleyicilerin TV\'deki şiddeti izlemesi "rezonans" (çifte doz) etkisi yaratarak korku algısını pekiştirir.'),
  ('Birinci düzey gündem belirleme medyanın "hangi konunun" önemli olduğunu aktarmasıyken, ikinci düzey gündem belirleme (nitelik gündemi) aşağıdakilerden hangisine odaklanır?', 'Konunun hangi özellik ve niteliklerle sunulduğuna', ['Haberin günün hangi saat diliminde yayımlandığına', 'İzleyicinin haberi hangi kitle iletişim aracından aldığına', 'Editörlerin haber kaynağını doğrulama yöntemlerine'], 'İkinci düzey gündem belirleme, nesnelerin kendisinden ziyade nesnelere atfedilen niteliklerin (alt boyutların ve duygu tonunun) izleyici zihnine aktarılmasını inceler.'),
  ('1993 tarihli makalesiyle iletişim biliminde dağınık halde bulunan çerçeveleme kavramını "seçme ve belirginleştirme" ilkeleri etrafında kuramsal bir paradigmaya dönüştüren akademisyen kimdir?', 'Robert Entman', ['Shanto Iyengar', 'Everett Rogers', 'Wilbur Schramm'], 'Robert Entman, çerçevelemeyi "algılanan gerçekliğin bazı yönlerini seçip iletişim metninde daha belirgin hale getirerek sorun tanımı ve çözüm önerisi sunmak" olarak tanımlamıştır.'),
  ('Shanto Iyengar\'ın araştırmalarına göre, toplumsal sorunların sürekli "epizodik çerçevelerle" haberleştirilmesinin kamuoyu algısı üzerindeki temel sonucu nedir?', 'Sorunun kaynağının sistem yerine bireylerde aranması', ['Hükümet politikalarına yönelik eleştirel taleplerin artması', 'Seçmenlerin istatistiksel verilere olan güveninin yükselmesi', 'Kamuoyunda uzun vadeli yapısal reform bilincinin oluşması'], 'Epizodik haberleme izleyiciyi somut kişilere odakladığı için işsizlik veya suç gibi sorunlarda kamu kurumlarının yapısal sorumluluğunu görünmez kılar.'),
  ('Kitle iletişim araçları toplumda bilgi akışını artırdıkça, sosyoekonomik düzeyi yüksek grupların bilgiyi düşük gruplardan daha hızlı edinerek aradaki farkı açtığını savunan kuram hangisidir?', 'Bilgi Gediği Hipotezi', ['Suskunluk Sarmalı Kuramı', 'Gündem Karıştırma Modeli', 'Üçüncü Kişi Etkisi'], 'Tichenor, Donohue ve Olien tarafından 1970\'te ortaya atılan Bilgi Gediği (Knowledge Gap) hipotezi, medya bolluğunun bilgi eşitsizliğini kendiliğinden kapatmadığını gösterir.'),
  ('Üçüncü Kişi Etkisi kuramının davranışsal boyutu dikkate alındığında, medyanın başkalarını olumsuz etkilediğine güçlü biçimde inanan bireylerde hangi tutumun gelişmesi beklenir?', 'Medya içeriklerine yönelik sansür ve kısıtlama taleplerini destekleme', ['Farklı görüşteki haber kanallarını daha fazla takip etmeye başlama', 'Kendi medya tüketim sürelerini gönüllü olarak sıfıra indirme', 'Geleneksel gazetecilik yerine yalnızca yurttaş gazeteciliğine güvenme'], 'Araştırmalar, diğer insanların medyadan kolayca zehirleneceğini düşünen kişilerin "toplumu koruma" gerekçesiyle sansür yanlısı politikalara daha sıcak baktığını kanıtlamıştır.'),
  ('Hadley Cantril\'in 1938 "Dünyalar Savaşı" radyo paniği üzerine yaptığı araştırma, erken dönem medya kuramları açısından hangi önemli gerçeği ortaya koymuştur?', 'Eleştirel düşünme ve eğitim düzeyinin medya paniğine direnç sağladığını', ['Radyo dinleyicilerinin tamamının istisnasız aynı korku tepkisini verdiğini', 'Kitle iletişim araçlarının insanları hipnotize etme gücünün sınırsız olduğunu', 'Yazılı basının radyoya kıyasla duygusal panik yaratmada daha etkili olduğunu'], 'Cantril\'in çalışması, her dinleyicinin paniğe kapılmadığını; eleştirel yetenek, dindarlık ve duygusal güvensizlik gibi bireysel farkların medya etkisini sınırlandırdığını göstermiştir.'),
  ('Herman ve Chomsky\'nin Propaganda Modeli\'ndeki "beş süzgeç"ten biri olan "tepki üretimi" (flak) kavramı aşağıdakilerden hangisini tanımlar?', 'Güçlü odakların medyayı hizaya getirmek için yürüttüğü dava, boykot ve baskı kampanyalarını', ['İzleyicilerin sosyal medyada sevdikleri diziler hakkında yaptıkları olumlu paylaşımları', 'Gazetelerin tirajlarını artırmak için okurlara dağıttığı promosyon ürünlerini', 'Haber ajanslarının son dakika gelişmelerini abonelere geçerken kullandığı şifreleme sistemini'], '"Flak", medya kuruluşları egemen çizginin dışına çıktığında hükümetler, şirketler veya düşünce kuruluşları tarafından organize edilen pahalı itiraz, şikayet ve yıldırma tepkileridir.'),
  ('1965 yılında yayımladıkları makaleyle bir olayın dış haber bültenlerine girme olasılığını belirleyen "haber değerleri" (eşik, olumsuzluk, seçkin uluslar vb.) listesini sistematikleştiren araştırmacılar kimlerdir?', 'Johan Galtung ve Mari Holmboe Ruge', ['Maxwell McCombs ve Donald Shaw', 'Pamela Shoemaker ve Stephen Reese', 'Elihu Katz ve Paul Lazarsfeld'], 'Galtung ve Ruge, uluslararası krizlerin Norveç basınında nasıl yer bulduğunu inceleyerek sıklık, eşik, belirsizlikten arınmışlık, anlamlılık ve olumsuzluk gibi 12 haber değeri belirlemiştir.'),
  ('Pamela Shoemaker ve Stephen Reese\'in haber içeriğini şekillendiren faktörleri iç içe geçmiş halkalar halinde açıkladığı "Etkiler Hiyerarşisi Modeli"nde en dış (en kapsayıcı) halkada hangisi yer alır?', 'Toplumsal sistem ve ideoloji', ['Gazetecinin bireysel özellikleri', 'Medya rutini ve mesleki normlar', 'Medya kuruluşunun kurumsal yapısı'], 'Shoemaker ve Reese\'in 5 katmanlı modelinde merkezden dışa doğru bireysel düzey, medya rutinleri, örgütsel düzey, medya dışı kurumsal düzey ve en dışta ideolojik/toplumsal sistem yer alır.'),
  ('Suskunluk Sarmalı kuramında dışlanma korkusuna boyun eğmeyerek kendi görüşleri azınlıkta kalsa bile bunu yüksek sesle savunmaya devam eden kararlı gruplara Noelle-Neumann ne ad verir?', 'Çekirdek grup (Hardcore)', ['Kanaat önderleri (Opinion leaders)', 'Eşik bekçileri (Gatekeepers)', 'Sessiz çoğunluk (Silent majority)'], 'Noelle-Neumann\'a göre "çekirdekler" (hardcore) ve "avangartlar", dışlanma bedelini ödemeye hazır oldukları için sarmalı kırarak toplumsal değişimi başlatabilen gruplardır.'),
  ('1980 yılında iki karşıt görüşlü öğrenci grubuna idam cezası hakkındaki aynı dengeli makaleleri okutup her iki grubun da medyayı "kendi görüşüne karşı taraflı" bulduğunu saptayan olguya ne ad verilir?', 'Düşmanca Medya Etkisi', ['Acımasız Dünya Sendromu', 'Bumerang Etkisi', 'Kültürel Gecikme Etkisi'], 'Vallone, Ross ve Lepper (1985) tarafından Orta Doğu haberleri üzerinden kavramsallaştırılan Düşmanca Medya Etkisi (Hostile Media Effect), güçlü partizanların tarafsız haberi bile karşı tarafa yanlı algılamasıdır.'),
  ('Gündem Belirleme Kuramının son evrelerinden biri olan "Ağ Gündemi Belirleme" (Üçüncü Düzey Gündem Belirleme) modeli aşağıdakilerden hangisini savunur?', 'Medyanın konuları ve nitelikleri tek tek değil, birbiriyle bağlantılı zihinsel ağ demetleri halinde aktardığını', ['Yalnızca sosyal medya fenomenlerinin ulusal televizyon kanallarının gündemini belirleyebildiğini', 'Seçmenlerin karar verirken en fazla üç farklı haber kaynağını karşılaştırabildiğini', 'İnternet hızının düşük olduğu bölgelerde kamuoyu oluşumunun tamamen durduğunu'], 'Maxwell McCombs ve Lei Guo\'nun geliştirdiği Üçüncü Düzey (Network Agenda Setting), medyanın farklı konular ve nitelikler arasında kurduğu ilişki ağlarını izleyici zihnine bir bütün (demet) olarak kopyaladığını belirtir.'),
  ('Daniel Hallin ve Paolo Mancini\'nin "Medya Sistemlerinin Karşılaştırılması" adlı eserinde yüksek siyasi paralellik, devlet müdahalesi ve yorum ağırlıklı gazetecilikle tanımlanan model hangisidir?', 'Kutupsallaşmış Çoğulcu (Akdeniz) Model', ['Liberal (Kuzey Atlantik) Model', 'Demokratik Korporatist (Kuzey Avrupa) Model', 'Sosyal Sorumluluk (Asya-Pasifik) Model'], 'Hallin ve Mancini batı medyasını üç modele ayırır; İtalya, İspanya ve Yunanistan gibi ülkeleri kapsayan Kutupsallaşmış Çoğulcu modelde basın ile siyasi partiler arasında güçlü paralellik görülür.'),
  ('Medya gündeminin kendi kendine oluşmadığını; siyasal aktörler, halkla ilişkiler şirketleri ve diğer seçkin haber kuruluşları tarafından nasıl şekillendirildiğini inceleyen araştırma alanına ne ad verilir?', 'Gündem İnşası (Agenda Building)', ['Gündem Belirleme (Agenda Setting)', 'Kültürel Ekme (Cultivation)', 'Alımlama Analizi (Reception Analysis)'], 'Gündem belirleme "medya gündeminin halk gündemine etkisini" incelerken, Gündem İnşası (Lang ve Lang; Cobb ve Elder) "medya gündemini kimin ve nasıl oluşturduğunu" araştırır.'),
  ('Daniel Boorstin\'in 1961\'de ortaya attığı ve kendiliğinden gerçekleşmeyip sırf medyada haber olması, fotoğraf verilmesi veya televizyonda yayımlanması amacıyla planlanan olayları tanımlayan kavram nedir?', 'Sözde olay (Pseudo-event)', ['Eşik olayı (Threshold event)', 'Siyah kuğu olayı (Black swan)', 'Odaklayıcı olay (Focusing event)'], 'Basın toplantıları, kurdele kesme törenleri veya planlı protesto şovları Boorstin\'in "sözde olay" kavramına örnektir; bu olayların varlık nedeni medya tarafından kaydedilmektir.'),
  ('Harold Lasswell\'in 1948 yılında kitle iletişim sürecini çözümlemek için ortaya koyduğu ünlü "5S" formülünün doğru sıralaması aşağıdakilerden hangisidir?', 'Kim, Neyi, Hangi kanalla, Kime, Hangi etkiyle söylüyor?', ['Ne zaman, Nerede, Nasıl, Niçin ve Kiminle tartışılıyor?', 'Kaynak, Gürültü, Kodlayıcı, Geri bildirim ve Eşik bekçisi nedir?', 'Üretici, Reklamveren, Editör, Muhabir ve Okuyucu kimdir?'], 'Lasswell\'in doğrusal iletişim modeli "Kim (kaynak analizi), Neyi (içerik analizi), Hangi kanalla (medya analizi), Kime (izleyici analizi), Hangi etkiyle (etki analizi) söylüyor?" sorularından oluşur.'),
  ('Bilişsel psikolojide Daniel Kahneman ve Amos Tversky\'nin "Asya hastalığı problemi" deneyinde, aynı tıbbi müdahalenin "600 kişiden 200\'ü kurtulacak" ile "400\'ü ölecek" şeklinde sunulmasının kararları değiştirmesi neyi kanıtlar?', 'Eşdeğerlik çerçevelemesi etkisini', ['Suskunluk sarmalı korkusunu', 'Bilgi gediği eşitsizliğini', 'İki aşamalı akış sürecini'], 'Mantıksal olarak tamamen aynı olan iki bilginin "kazanç" veya "kayıp" dilinde çerçevelenmesinin insan tercihlerini tersine çevirmesine eşdeğerlik çerçevelemesi (equivalency framing) denir.'),
  ('Gündem Belirleme araştırmalarında kullanılan "yönelim ihtiyacı" (need for orientation) kavramına göre, bir bireyin medya gündeminden en yüksek düzeyde etkilenmesi hangi iki koşulun birleşimine bağlıdır?', 'Konunun birey için öneminin yüksek ve konu hakkındaki belirsizliğin fazla olması', ['Konunun birey için önemsiz ve bireyin konu hakkındaki bilgisinin tam olması', 'Bireyin eğitim düzeyinin yüksek ve televizyon izleme süresinin sıfır olması', 'Konunun tarihsel geçmişinin çok eski ve toplumsal uzlaşının kesin olması'], 'David Weaver ve Maxwell McCombs\'a göre bireyin bir konuya ilgi/alaka düzeyi yüksek, ancak o konudaki bilgisi yetersiz (belirsizlik yüksek) ise yönelim ihtiyacı zirveye çıkar ve medya etkisi artar.'),
  ('Seçim öncesi kamuoyu araştırmalarının medyada yayımlanması sonucunda, seçmenlerin sırf "kazanan tarafta yer alma" psikolojisiyle önde görünen adaya yönelmesine ne ad verilir?', 'Bando arabası (Bandwagon) etkisi', ['Mazlum (Underdog) etkisi', 'Bumerang (Ters tepme) etkisi', 'Uyuyan güzel (Sleeper) etkisi'], 'Bandwagon (bando arabası) etkisi, anketlerde güçlü ve zaferi kesin görünen adayın kararsız seçmenleri kendi saflarına çekmesi; Underdog etkisi ise geride kalana sempati duyulmasıdır.'),
  ('Frankfurt Okulu düşünürleri Max Horkheimer ve Theodor W. Adorno\'nun, medyanın sanatı ve eğlenceyi standartlaşmış ticari metalara dönüştürerek kitleleri pasifleştirdiğini anlattıkları kavram nedir?', 'Kültür Endüstrisi', ['Kamusal Alan', 'Küresel Köy', 'Kullanımlar ve Doyumlar'], 'Adorno ve Horkheimer, 1947 tarihli "Aydınlanmanın Diyalektiği" eserinde sinema, radyo ve dergilerin kitleleri eleştirel düşünceden uzaklaştıran bir "Kültür Endüstrisi" oluşturduğunu savunmuştur.'),
  ('Elisabeth Noelle-Neumann\'ın 1973 tarihli makalesiyle "Güçlü Medya Etkileri Kavramına Dönüş" çağrısı yaparken, medyanın etkisini güçlü kıldığını savunduğu üç temel özellik hangileridir?', 'Birikimlilik, her yerde bulunurluk ve ünsiyet', ['Etkileşimlilik, kişiselleştirme ve hız', 'Tarafsızlık, çok seslilik ve kamusal denetim', 'Ucuzluk, taşınabilirlik ve görsel çözünürlük'], 'Noelle-Neumann\'a göre medya mesajlarının sürekli tekrarlanması (kümülatiflik/birikim), her mecrada karşımıza çıkması (ubiquity) ve gazetecilerin benzer çerçeveler sunması (consonance) seçici algıyı kırar.'),
  ('Gaye Tuchman\'ın haber sosyolojisi araştırmalarına göre "haber ağı" (beat) sisteminin kamuoyu oluşumu açısından yarattığı en önemli yapısal sınırlılık nedir?', 'Resmî ve kurumsal kaynakların görüşlerini ayrıcalıklı kılıp sivil/örgütsüz kesimleri görünmezleştirmesi', ['Muhabirlerin devlet kurumlarından bilgi almasını tamamen imkânsız hale getirmesi', 'Haber bültenlerinde hiç siyaset ve ekonomi haberine yer verilememesine yol açması', 'Gazetelerin baskı maliyetlerini artırarak yerel basının anında kapanmasına sebep olması'], 'Haber ağları mahkeme, bakanlık ve polis merkezlerine kurulduğu için kurumsal yetkililer "birincil tanımlayıcılar" haline gelirken kurumsal temsili olmayan yurttaşların sorunları ağın dışında kalır.'),
  ('Dijital medya literatüründe sıklıkla birbiriyle karıştırılan "filtre balonu" ile "yankı odası" arasındaki temel kavramsal fark aşağıdakilerden hangisidir?', 'Filtre balonu algoritmik kişiselleştirmeden, yankı odası ise sosyal ağlardaki homojen grup tercihinden kaynaklanır', ['Filtre balonu yalnızca basılı gazetelerde, yankı odası ise yalnızca radyo yayınlarında görülür', 'Filtre balonu kullanıcının bilinçli tercihidir, yankı odası ise devlet sansürüyle zorla kurulur', 'Filtre balonu yanlış bilgiyi engellerken yankı odası bilimsel makalelerin yayılmasını hızlandırır'], 'Filtre balonu görünmez yazılım algoritmalarının teknik filtrelemesine vurgu yaparken, yankı odası insanların kendilerine benzeyenlerle kurduğu sosyal ve topluluksal ağ yapısını (homofili) vurgular.'),
  ('Claire Wardle\'ın yanlış ve yanıltıcı içerikleri incelediği 7\'li tipolojide, gerçek bir kurumun veya ünlü bir haber sitesinin logosu ve tasarımı birebir taklit edilerek üretilen sahte içeriklere ne denir?', 'Taklit içerik (Imposter content)', ['Hiciv ve parodi (Satire)', 'Hatalı ilişkilendirme (False connection)', 'Çarpıtılmış içerik (Manipulated content)'], 'Taklit içerik (imposter content), okurun tanınmış haber markalarına duyduğu güveni istismar etmek için sahte alan adları ve kopyalanmış kurumsal logolarla uydurma haber yaymaktır.'),
  ('Siyasal iletişim ve halkla ilişkilerde, güçlü bir lobinin veya şirketin yürüttüğü organize kampanyayı sanki halktan kendiliğinden doğmuş samimi bir taban hareketiymiş gibi göstermesine ne ad verilir?', 'Astroturfing (Yapay çim hareketi)', ['Crowdfunding (Kitlesel fonlama)', 'Fact-checking (Doğruluk kontrolü)', 'Whistleblowing (Bilgi uçurma)'], 'İngilizcede gerçek taban hareketlerine "grassroots" (çim kökleri) denmesine karşılık, sahte/sentetik çim markası AstroTurf\'ten türetilen "astroturfing", sahte halk desteği imalatını tanımlar.'),
  ('Şüpheli bir internet sitesindeki iddiayı araştıran bir doğruluk kontrolcüsünün (fact-checker), sekme açarak bizzat o sitenin kendi "Hakkımızda" sayfasını okumak yerine o siteyi dışarıdan bağımsız kaynaklarda araştırmasına ne denir?', 'Yatay okuma (Lateral reading)', ['Dikey okuma (Vertical reading)', 'Yüzeysel tarama (Skimming)', 'Seçici okuma (Selective reading)'], 'Stanford Üniversitesi araştırmacılarının (Sam Wineburg vd.) tanımladığı yatay okuma, şüpheli sitenin içinde vakit kaybetmek yerine yeni sekmeler açıp sitenin güvenilirliğini dış kaynaklardan sorgulamaktır.'),
  ('Psikolojide yanlış ve uydurma bir iddianın bile kitle iletişiminde veya sosyal medyada sürekli tekrar edilmesi sonucunda insanlara daha doğru ve inandırıcı gelmeye başlamasına ne ad verilir?', 'Yanılsamalı gerçeklik etkisi (Illusory truth effect)', ['Üçüncü kişi etkisi (Third-person effect)', 'Düşmanca medya algısı (Hostile media perception)', 'Bilişsel tükenmişlik sendromu'], 'Hasher, Goldstein ve Toppino (1977) tarafından keşfedilen yanılsamalı gerçeklik etkisine göre, tekrarlanan bilgi beyinde "bilişsel akıcılık" (işleme kolaylığı) yarattığı için beyin tanıdıklığı doğrulukla karıştırır.'),
  ('Dezenformasyonla mücadelede "gerçek sandviçi" (truth sandwich) olarak bilinen etkili düzeltme tekniğinin doğru sıralaması aşağıdakilerden hangisidir?', 'Önce doğru olguyu söylemek, ardından yanlışı kısaca belirtip nedenini açıklamak ve tekrar doğru olguyla bitirmek', ['Önce yanlış iddiayı detaylıca anlatmak, ortada doğruyu verip sonda tekrar yanlış iddiayı hatırlatmak', 'Hiçbir olgusal kanıt sunmadan yalnızca komplo teorisi üreten kişilerin isim listesini yayımlamak', 'Doğru bilgiyi gizli tutup okuyucudan kendi araştırmasını yaparak gerçeği bulmasını istemek'], 'Dilbilimci George Lakoff\'un önerdiği gerçek sandviçi (hakikat sandviçi) yönteminde çerçeveyi doğru bilgi belirler: Doğruyla başlanır, yanılgıya dikkat çekilir ve zihinde kalması için doğruyla kapatılır.'),
  ('Bir bireyin kendi siyasi kimliğiyle çelişen somut kanıtlar ve doğrulama raporlarıyla karşılaştığında, hatasını kabul etmek yerine yanlış inancına eskisinden daha sıkı sarılmasına ne ad verilir?', 'Geri tepme etkisi (Backfire effect)', ['Uyuyan etki (Sleeper effect)', 'Anaakımlaştırma etkisi (Mainstreaming)', 'Yöndeşme etkisi (Convergence)'], 'Nyhan ve Reifler\'in incelediği geri tepme etkisi, kimliği tehdit eden düzeltmeler karşısında bireyin "güdülenmiş akıl yürütme" (motivated reasoning) yaparak mevcut yanlış inancını savunmacı biçimde güçlendirmesidir.'),
  ('Manuel Castells\'in dijital çağda sosyal medya ve mobil ağlar üzerinden bireyin kendi ürettiği mesajı potansiyel olarak küresel bir kitleye ulaştırabilmesini tanımlamak için geliştirdiği kavram hangisidir?', 'Kitlesel öz-iletişim (Mass self-communication)', ['İki aşamalı kişilerarası akış', 'Tek yönlü yayıncılık (Broadcasting)', 'Bürokratik dikey iletişim'], 'Castells\'e göre YouTube videosu veya X paylaşımı potansiyel olarak tüm dünyaya ulaşabildiği için "kitlesel", ancak içeriğin üretimi ve hedef seçimi bireyin kendisi tarafından yapıldığı için "öz-iletişim"dir.'),
  ('Sosyal medya platformlarının reklam gelirlerini artırmak için kullanıcıyı ekranda daha uzun tutmayı hedefleyen "dikkat ekonomisi" modeli, haber ekosisteminde hangi içerik türünü yapısal olarak ödüllendirir?', 'Öfke, korku ve ahlaki infial uyandıran kutuplaştırıcı içerikleri', ['Uzun, sakin ve çok boyutlu akademik araştırma raporlarını', 'Taraflar arasında uzlaşı arayan nüanslı ve ılımlı analizleri', 'Okuyucuyu ekranı kapatıp kitap okumaya teşvik eden metinleri'], 'Algoritmalar etkileşimi (yorum, paylaşım, tepki) maksimize etmeye ayarlandığı için, yüksek uyarılmışlık yaratan öfke ve ahlaki infial içerikleri sakin ve doğrulanmış haberlerden çok daha hızlı yayılır.'),
  ('Eleştirel medya okuryazarlığında bir metni çözümlerken sorulan "Bu mesajda hangi yaşam tarzları, değerler ve bakış açıları temsil ediliyor ya da hangileri dışarıda bırakılıyor?" sorusu neyi ortaya çıkarmayı amaçlar?', 'Metnin ideolojik alt metnini ve görünmez kılınan toplumsal grupları', ['Haberin yayımlandığı sunucunun teknik bant genişliği kapasitesini', 'Metni yazan muhabirin mezun olduğu üniversitenin kuruluş tarihini', 'Yayın kuruluşunun kullandığı kamera lenslerinin optik odak uzaklığını'], 'Eleştirel medya okuryazarlığı sadece metinde "ne söylendiğine" değil, "neyin söylenmediğine" (sessizliklere ve dışlamalara) bakarak güç ilişkilerini ve ideolojik çerçeveyi deşifre eder.'),
  ('Devlet destekli veya organize trol ağlarının, muhalif bir gazeteciyi doğrudan sansürlemek yerine hesabına binlerce hakaret, tehdit ve alakasız spam göndererek sesini duyulmaz hale getirmesi hangi stratejidir?', 'Gürültüyle boğma / Taşkın sansür', ['Geleneksel yayın öncesi matbaa sansürü', 'Yatay okuma ve çapraz doğrulama yöntemi', 'Kamu hizmeti yayıncılığı denetimi'], 'Zeynep Tüfekçi ve Margaret Roberts gibi araştırmacıların incelediği modern dijital sansürde, içeriği silmek yerine bilgi akışını trol orduları ve yanıltıcı gürültüyle boğarak hedefi yıldırma yöntemi uygulanır.'),
  ('Medya ekonomisinde mülkiyet yoğunlaşmasının ve holdingler arası çapraz tekelleşmenin demokratik kamuoyu oluşumu üzerindeki en kritik olumsuz etkisi aşağıdakilerden hangisidir?', 'İçerik çeşitliliğini azaltıp holdingin ticari-siyasi çıkarlarıyla çelişen haberlerde otosansürü artırması', ['Gazete ve televizyon bültenlerindeki görüntü kalitesinin teknik olarak düşmesine yol açması', 'Medya şirketlerinin reklam ajanslarıyla sözleşme imzalamasını hukuken imkânsız kılması', 'Muhabirlerin bilgisayar ve kamera gibi teknolojik ekipmanlara erişimini engellemesi'], 'Medya kuruluşları maden, enerji veya inşaat ihalelerine giren dev holdinglerin parçası olduğunda, gazeteciler grup şirketlerinin çıkarlarına dokunan konularda otosansür baskısıyla karşılaşır.'),
  ('İletişim araştırmalarında "birinci düzey dijital uçurum" internete fiziksel erişim farkını anlatırken, "ikinci düzey dijital uçurum" aşağıdakilerden hangisine odaklanır?', 'İnternete erişebilen bireyler arasındaki dijital beceri, üretim ve nitelikli kullanım eşitsizliğine', ['Ülkeler arasındaki fiber optik denizaltı kablolarının toplam uzunluk farkına', 'Masaüstü bilgisayar fiyatları ile dizüstü bilgisayar fiyatları arasındaki vergi oranına', 'Sabit telefon hatlarının kırsal köylere ulaştırılma süresindeki tarihsel gecikmeye'], 'Jan van Dijk ve Eszter Hargittai gibi araştırmacılara göre herkesin akıllı telefonu olsa bile kiminin interneti sadece pasif eğlence için, kiminin ise eğitim ve kariyer üretimi için kullanması ikinci düzey dijital uçurumdur.'),
  ('19. yüzyıl sonunda ABD\'de Joseph Pulitzer ve William Randolph Hearst\'ün gazeteleri arasındaki tiraj savaşlarında ortaya çıkan; sansasyon, abartı ve kışkırtıcı manşetlere dayalı habercilik anlayışına ne ad verilir?', 'Sarı gazetecilik (Yellow journalism)', ['Barış gazeteciliği (Peace journalism)', 'Yavaş gazetecilik (Slow journalism)', 'Çözüm gazeteciliği (Solutions journalism)'], 'Adını "The Yellow Kid" adlı çizgi bant karakterinden alan sarı gazetecilik, olgusal doğruluk yerine sansasyonel manşetler, skandallar ve duygusal kışkırtmayla gazete satma pratiğidir.'),
  ('Johan Galtung\'un çatışma haberciliğine getirdiği eleştiride, şiddeti sadece "kim kazanıyor, kim kaybediyor" şeklinde bir spor müsabakası gibi sunan geleneksel "savaş gazeteciliği"nin karşısına koyduğu alternatif model nedir?', 'Barış gazeteciliği', ['İliştirilmiş gazetecilik', 'Diplomatik protokol haberciliği', 'Ulusal güvenlik haberciliği'], 'Galtung\'un Barış Gazeteciliği modeli; çatışmayı iki taraf arasındaki sıfır toplamlı bir oyun gibi göstermek yerine çatışmanın yapısal köklerini, tüm tarafların acılarını ve şiddetsiz çözüm yollarını görünür kılar.'),
  ('Doğrulama uzmanları ve araştırmacı gazetecilerin; uydu görüntüleri, uçuş takip verileri, gölge açıları ve sosyal medya paylaşımları gibi halka açık dijital verileri birleştirerek olay yeri ve zamanını kanıtlamasına ne denir?', 'Açık kaynak istihbaratı', ['Kapalı devre mülakat tekniği', 'Klasik telefon anketi yöntemi', 'Psikanalitik söylem çözümlemesi'], 'OSINT (Open-Source Intelligence) gazeteciliğinde, örneğin bir videodaki güneşin gölge açısından saat hesaplanır ve Google Earth uydu görüntüleriyle binalar eşleştirilerek (coğrafi konumlama) kesin doğrulama yapılır.'),
  ('Daniel Kahneman\'ın "Hızlı ve Yavaş Düşünme" kuramı sosyal medya dezenformasyonuna uyarlandığında, insanların sahte haberlere inanma eğiliminin azalması aşağıdakilerden hangisine bağlıdır?', 'Sezgisel ve otomatik "Sistem 1" yerine çaba gerektiren analitik "Sistem 2" düşüncesinin devreye girmesine', ['Kullanıcıların haber başlıklarını bir saniyeden daha kısa sürede okuyup geçmesine', 'Sosyal medya bildirim seslerinin daha yüksek frekanslı tonlara ayarlanmasına', 'Haber metinlerinin yerine yalnızca hareketli emojilerin ve kısa videoların kullanılmasına'], 'Gordon Pennycook ve David Rand\'ın araştırmaları, insanların sahte haberleri çoğu kez yalnız partizanlıktan değil "bilişsel tembellik"ten (Sistem 1 ile hızlıca kaydırıp Sistem 2 analitik sorgulamasını açmamaktan) paylaştığını göstermiştir.'),
  ('Uluslararası Doğruluk Kontrolü Ağı\'nın (IFCN) güvenilir doğrulama kuruluşlarını akredite ederken şart koştuğu temel ilkeler arasında aşağıdakilerden hangisi yer alır?', 'Partizan olmama, kaynakların ve finansmanın şeffaflığı ile açık düzeltme politikası', ['Yalnızca hükûmet sözcülerinin onayladığı bültenleri doğru kabul etme zorunluluğu', 'Haber kaynaklarını ve kanıt yöntemlerini ticari sır kapsamında gizli tutma', 'Hata yapıldığında kurum itibarını korumak için eski raporları sessizce silme'], 'Poynter Enstitüsü bünyesindeki IFCN İlkeler Kodu; tarafsızlık/hakkaniyet, kaynak şeffaflığı, mali ve örgütsel şeffaflık, metodoloji şeffaflığı ve dürüst/açık düzeltme taahhüdünü zorunlu tutar.'),
  ('Üretken yapay zekâ araçlarının metin, ses ve görüntü üretim maliyetini neredeyse sıfıra indirmesi, dijital dezenformasyon ekosistemi açısından hangi yapısal dönüşümü beraberinde getirmiştir?', 'Kişiselleştirilmiş ve çok dilli sahte içeriklerin kitlesel ölçekte hızla üretilebilmesini', ['İnternetteki tüm anonim hesapların otomatik olarak gerçek kimlikleriyle eşleşmesini', 'Geleneksel basılı gazetelerin tirajlarının dijital medyanın önüne geçmesini', 'Doğrulama kuruluşlarının hiçbir insan emeğine ihtiyaç duymadan kapanmasını'], 'Geçmişte ikna edici sahte içerik üretmek zaman ve bütçe gerektirirken, üretken yapay zekâ dezenformasyon aktörlerine her hedef kitleye özel binlerce farklı varyasyonu anında üretme kapasitesi vermiştir.'),
  ('Son yıllarda Reuters Enstitüsü Dijital Haber Raporlarında giderek yükseldiği saptanan "seçici haberden kaçınma" (selective news avoidance) davranışının temel psikolojik nedeni aşağıdakilerden hangisidir?', 'Sürekli kriz ve kutuplaşma haberlerinin bireylerde duygusal tükenmişlik ve çaresizlik hissi yaratması', ['İnternet kullanıcılarının dünyada hiçbir önemli siyasi veya ekonomik olay yaşanmadığını düşünmesi', 'Akıllı telefon ve bilgisayar ekranlarının haber sitelerini açamayacak kadar yavaşlaması', 'Vatandaşların tüm güncel bilgileri yalnızca basılı ansiklopedilerden takip etmeye başlaması'], 'Haber yorgunluğu (news fatigue) ve olumsuz gündemin yarattığı ruhsal yıpranma nedeniyle, birçok yurttaş ruh sağlığını korumak amacıyla haber bültenlerini bilinçli olarak izlemeyi bırakmaktadır.'),
  ('Sosyal medya çalışmalarında kullanılan "bağlam çökmesi" (context collapse) kavramı, bireylerin dijital kamusal alanda yaşadığı hangi iletişimsel gerilimi açıklar?', 'Aile, iş arkadaşları, patron ve lise dostları gibi normalde ayrı tutulan farklı sosyal çevrelerin tek bir profilde aynı anda izleyici haline gelmesini', ['İnternet altyapısındaki fiber kabloların aşırı yüklenme nedeniyle aynı anda devre dışı kalmasını', 'Uzun gazete makalelerinin özetlenirken dilbilgisi ve yazım kurallarının tamamen bozulmasını', 'Tarihsel arşiv belgelerinin dijital ortama aktarılırken tarih sıralamasının karışmasını'], 'Alice Marwick ve danah boyd\'un incelediği bağlam çökmesi, gerçek hayatta her gruba göre ayarlanan sosyal rollerin sosyal medyada tek bir paylaşımda çakışması ve öz-sansürü tetiklemesidir.'),
  ('Shannon ve Weaver\'ın "Matematiksel İletişim Kuramı" başlangıçta hangi pratik sorunu çözmek amacıyla Bell Telefon Laboratuvarları\'nda tasarlanmıştır?', 'Telefon ve telgraf hatlarında bilginin en az kayıpla ve en yüksek kapasiteyle iletilmesini sağlamak', ['Seçmenlerin siyasal kampanya dönemlerindeki oy verme davranışlarını yönlendirmek', 'Televizyon yayınlarının çocukların saldırganlık eğilimleri üzerindeki etkisini ölçmek', 'Farklı kültürlerden gelen diplomatlar arasındaki beden dili uyuşmazlıklarını gidermek'], 'Shannon-Weaver modeli özünde mühendislik temelli olup telekomünikasyon hatlarındaki sinyal verimliliğini artırmak için geliştirilmiştir.'),
  ('Bir konuşmacının kurduğu cümlenin kelimeleri olumlu olduğu halde ses tonunun titremesi, konuşma hızının artması ve vurgularının alaycı olması sözsüz iletişimin hangi boyutuyla doğrudan ilgilidir?', 'Dilin ötesi (paralinguistik)', ['Kişiler arası mekan (proksemik)', 'Dokunsal temas (haptik)', 'Nesnel çevre düzeni (artefakt)'], 'Sesin tonu, yüksekliği, hızı, duraksamalar ve vurgular kelimelerin kendisi değil söyleniş biçimi olduğundan paralinguistik kapsamındadır.'),
  ('Carl Rogers ve Richard Farson tarafından kavramsallaştırılan "etkin dinleme" (active listening) yaklaşımının temel varsayımı aşağıdakilerden hangisidir?', 'Yargılamadan ve empatiyle dinlenen bireyin savunma mekanizmalarının azalacağı ve kendi çözümünü bulabileceği', ['Dinleyicinin konuşmacıya hızlıca uzman tavsiyesi vermesinin sorunu en kısa sürede çözeceği', 'İletişimde sözlü mesajların her zaman beden dilinden daha güvenilir bilgi taşıdığı', 'Başarılı bir dinlemenin konuşmacının fikirlerini dinleyicinin değer yargılarına göre düzeltmesi olduğu'], 'Hümanist psikoloji temelli etkin dinleme, koşulsuz kabul ve empatik anlayışla bireyin kendi içgörüsünü geliştirmesini hedefler.'),
  ('Shannon-Weaver modelindeki "entropi" (belirsizlik) ve "artıklık" (redundancy) kavramları arasındaki ilişki açısından, bir mesajdaki artıklığın yükseltilmesi ne işe yarar?', 'Kanaldaki gürültüye karşı mesajın doğru anlaşılma olasılığını artırır ancak iletilen yeni bilgi miktarını düşürür', ['Mesajın iletim hızını sonsuza çıkararak tüm anlamsal belirsizlikleri ortadan kaldırır', 'Kaynağın kodlama yapma zorunluluğunu kaldırarak doğrudan zihinsel aktarım sağlar', 'Alıcının geri bildirim verme yeteneğini tamamen engelleyerek iletişimi sonlandırır'], 'Artıklık (tekrarlar ve öngörülebilir kalıplar), gürültülü kanallarda hata payını azaltır fakat enformasyon kuramına göre sürpriz/yeni bilgi değerini azaltır.'),
  ('Bireyin stres altındayken farkında olmadan kalemle oynaması, saçını burması veya yakasını çekiştirmesi Ekman ve Friesen\'in kinesik tipolojisinde hangi kavramla adlandırılır?', 'Adaptörler (uyarlayıcılar)', ['Amblemler', 'Açıklayıcılar (illüstratörler)', 'Sözel kodlayıcılar'], 'Adaptörler, içsel gerilimi yatıştırmak veya bedensel bir ihtiyacı karşılamak üzere çoğu kez bilinçdışı yapılan hareketlerdir.'),
  ('Bir kişi arkadaşına "Beni hiç umursamadığını hissediyorum" dediğinde, cümlede "hissediyorum" kelimesi geçmesine rağmen bunun gerçek bir "ben dili" sayılmamasının nedeni nedir?', 'Bir duyguyu değil, karşı tarafın niyetine ilişkin suçlayıcı bir yorumu "hissediyorum" kelimesinin arkasına gizlemesi', ['Cümlenin içinde birinci tekil şahıs zamirinin açık biçimde yazılmamış olması', 'Konuşmacının ses tonunun yüksekliğine dair paralinguistik bir veri sunmaması', 'Dinleyicinin geri bildirim vermesini engelleyen mekanik bir gürültü yaratması'], '"Umursamadığını hissediyorum" ifadesi gerçekte bir duygu (üzüntü, kırgınlık) değil, karşı tarafı yargılayan örtük bir "sen dili" düşüncesidir.'),
  ('Roman Jakobson\'un dil ve iletişim işlevleri modelinde, "Alo, sesim geliyor mu?" gibi kanalın açık olup olmadığını kontrol etmeye yönelik ifadeler iletişimin hangi işlevini örneklendirir?', 'İlişki (fatik / kanalı kontrol) işlevi', ['Şiirsel (poetik) işlev', 'Üstdil (metalinguistik) işlevi', 'Göndergesel (bilgi verici) işlev'], 'Jakobson\'da fatik (ilişki) işlev, iletişim kanalının çalışıp çalışmadığını sınamaya ve teması sürdürmeye yöneliktir.'),
  ('David Berlo\'nun SMCR modeline göre, hem kaynağın hem de alıcının iletişim başarısını belirleyen dört ortak nitelik aşağıdakilerin hangisinde doğru verilmiştir?', 'İletişim becerileri, tutumlar, bilgi düzeyi, toplumsal-kültürel sistem', ['Fiziksel güç, ekonomik gelir, coğrafi konum, biyolojik yaş', 'Telefon hattı kalitesi, uydu frekansı, elektrik akımı, bant genişliği', 'Reklam bütçesi, yayın saati, tiraj oranı, sansür mekanizması'], 'Berlo modelinde kaynak ve alıcı simetrik olarak iletişim becerileri, tutumlar, bilgi düzeyi ve sosyokültürel sistem faktörleriyle tanımlanır.'),
  ('Theodore Newcomb\'un 1953 tarihli "ABX İletişim Modeli" sosyal psikolojideki hangi temel ilkeye dayanmaktadır?', 'İki bireyin (A ve B) ortak bir nesneye (X) yönelik tutumları arasında uyumsuzluk olduğunda denge kurmak için iletişime geçme eğilimi göstermesine', ['Kitle iletişim araçlarının (X) izleyici kitleyi (A ve B) hiçbir dirençle karşılaşmadan aynı anda hipnotize etmesine', 'Telefon santrallerindeki A ve B hatlarının X merkezinde minimum elektrik kaybıyla birleştirilmesine', 'Konuşmacının (A) dinleyiciye (B) her zaman X mesafesi kadar fiziksel uzaklıkta durmak zorunda olmasına'], 'Newcomb\'un ABX modeli, Heider\'in denge kuramından esinlenerek bireylerin tutum simetrisi (uyumu) sağlamak amacıyla iletişim kurduğunu açıklar.'),
  ('Albert Mehrabian\'ın yüz yüze iletişimde duygu ve tutumların aktarımı üzerine yaptığı ünlü araştırmaların sıklıkla yanlış genellenen bulgusu gerçekte hangi koşul için geçerlidir?', 'Sözlü mesaj ile ses tonu ve yüz ifadesi birbiriyle çeliştiğinde, alıcının konuşmacının duygusunu anlamak için sözsüz ipuçlarına ağırlık vermesi', ['Bilimsel bir konferansta sunulan matematiksel formüllerin %93 oranında konuşmacının el hareketlerinden öğrenilmesi', 'Radyo haberlerini dinleyen kişilerin haberin konusunu kelimelerden değil yalnızca spikerin yüz mimiklerinden anlaması', 'Yazılı mektup ve e-postalarda kelimelerin iletişime katkısının her koşulda %7 ile sınırlı kalması'], 'Mehrabian\'ın %7 söz - %38 ses - %55 yüz ifadesi kuralı genel bilgi aktarımı için değil, tutarsız/çelişkili duygu ve tutum ifadelerinin yorumlanması için geçerlidir.'),
  ('Thomas Gordon\'un iletişim engelleri sınıflandırmasında, üzgün bir kişiye "Neden böyle yaptın? Kiminle konuştun? Saat kaçta gittin?" şeklinde art arda kapalı uçlu sorular yöneltmek niçin bir engel sayılır?', 'Konuşmacıyı sorguya çekiliyormuş hissine sokarak asıl duygusundan uzaklaştırması ve savunmaya itmesi', ['Soru cümlelerinin Türkçede dilbilgisi açısından özne-yüklem uyumsuzluğu yaratması', 'Dinleyicinin işitme duyusunu geçici olarak devre dışı bırakarak fiziksel sağırlık oluşturması', 'İletişim ortamındaki tüm sözsüz ipuçlarını ortadan kaldırarak yazılı iletişime zorlaması'], 'Sorgulamak ve dedektiflik yapmak empatik akışı keser; odağı konuşmacının iç dünyasından dinleyicinin merakına kaydırır.'),
  ('Önyargılı bir dinleyicinin, sevmediği bir siyasetçinin yaptığı konuşmadaki mantıklı önerileri bile baştan reddederek çarpıtması hangi iletişim engeli kapsamında değerlendirilir?', 'Psikolojik gürültü ve seçici algı', ['Fiziksel kanal daralması', 'Paralinguistik ses kısıklığı', 'Proksemik kamusal mesafe'], 'Bireyin tutumları, önyargıları, kalıp yargıları ve duygusal dirençleri mesajın nesnel biçimde alımlanmasını bozan psikolojik gürültüdür.'),
  ('Michael Argyle ve Janet Dean tarafından geliştirilen "Yakınlık Dengesi Kuramı"na (Equilibrium Theory) göre, iki kişi arasındaki fiziksel mesafe beklenmedik şekilde azaldığında ne olması beklenir?', 'Rahatsızlığı azaltmak için göz temasının azaltılması, bedenin hafifçe yana çevrilmesi veya konunun resmileştirilmesi', ['Karşılıklı göz temasının kesintisiz hale getirilerek konuşma sesinin en üst düzeye çıkarılması', 'Tarafların derhal el sıkışarak kişisel sırlarını paylaşmaya başlaması', 'İletişim kanalındaki tüm anlamsal kodların kendiliğinden silinmesi'], 'Yakınlık dengesi kuramına göre fiziksel mesafe, göz teması, gülümseme ve konu mahremiyeti bir denge içindedir; biri aşırı artarsa diğeri azaltılarak denge korunur.'),
  ('Barnlund\'un "Etkileşimsel / İşlemsel (Transactional) İletişim Modeli", Schramm\'ın erken dönem dairesel modelini hangi yönden daha ileriye taşımıştır?', 'Kaynak ve alıcının sırayla değil, aynı anda hem mesaj gönderip hem de mesaj aldığını (eşzamanlılığı) vurgulamasıyla', ['İletişim sürecinden sözsüz ipuçlarını tamamen çıkararak yalnızca telgraf kodlarını incelemesiyle', 'Geri bildirimin yalnızca kitle iletişim araçlarında mümkün olduğunu ileri sürmesiyle', 'Mesajın anlamının alıcıdan bağımsız olarak yalnızca sözlük tanımlarında sabitlendiğini savunmasıyla'], 'İşlemsel (transactional) modelde iletişim masa tenisi gibi sırayla top atmak değil, konuşurken aynı anda karşı tarafın yüz ifadesini okumak gibi eşzamanlı ve ortak anlam inşasıdır.'),
  ('Gregory Bateson ve çalışma arkadaşlarının iletişim kuramına kazandırdığı "çifte açmaz" (double bind) kavramı aşağıdaki durumlardan hangisini tanımlar?', 'Aralarında güçlü bağ bulunan bir ilişkide, bir tarafın sözlü ve sözsüz düzeyde birbiriyle çelişen iki emir verip karşı tarafın bu çelişkiyi tartışmasını da engellemesi', ['Bir radyo istasyonunun aynı haberi hem sabah hem de akşam bülteninde hiç değiştirmeden yayınlaması', 'İki farklı ülkenin liderlerinin tercüman aracılığıyla diplomatik müzakere yürütmesi', 'Bir öğrencinin aynı gün içinde hem sayısal hem de sözel dersten sınava girmek zorunda kalması'], 'Çifte açmazda birey ne yaparsa yapsın kaybeder; örneğin soğukça itilip "Bana neden hiç sarılmıyorsun?" diye suçlanması gibi çelişkili mesajlar kıskacıdır.'),
  ('Paul Watzlawick ve Palo Alto Okulu\'nun Pragmatik İletişim Kuramı\'ndaki birinci ve en ünlü aksiyomu olan "İletişim kurmamak imkansızdır" ilkesi neyi savunur?', 'Sosyal bir ortamda susmanın, hareketsiz kalmanın veya arkasını dönmenin bile karşı tarafa mutlaka bir mesaj ilettiğini', ['İnsanların uyku halindeyken bile sürekli yüksek sesle konuşmak zorunda olduklarını', 'Teknolojik iletişim araçları olmadan toplumsal yaşamın bir saniye bile süremeyeceğini', 'Her iletişim girişiminin mutlaka tam bir uzlaşma ve ikna ile sonuçlandığını'], 'Watzlawick\'e göre her davranış bir iletişimdir; konuşmayı reddetmek de "seninle konuşmak istemiyorum" mesajını taşıyan bir iletişim eylemidir.'),
  ('Watzlawick\'in iletişim aksiyomlarına göre her iletişimin sahip olduğu iki temel düzey aşağıdakilerin hangisinde doğru eşleştirilmiştir?', 'İçerik (bilgi) düzeyi ve ilişki (mesajın nasıl anlaşılacağını belirleyen üst-iletişim) düzeyi', ['Mekanik iletim düzeyi ve termodinamik entropi düzeyi', 'Yerel ağız düzeyi ve uluslararası resmi diplomasi düzeyi', 'Kitle iletişim düzeyi ve folklorik sözlü kültür düzeyi'], 'Her ileti bir yandan veri/bilgi aktarır (içerik düzeyi), diğer yandan taraflar arasındaki ilişkinin niteliğini (emir, rica, şaka, saygı) tanımlar (ilişki düzeyi).'),
  ('Charles Osgood ve Wilbur Schramm\'ın modelinde her bireyin kendi içinde gerçekleştirdiği üç temel iletişimsel işlev aşağıdakilerin hangisinde eksiksiz verilmiştir?', 'Kodlama (encoding), yorumlama (interpreting) ve kod açma', ['Filtreleme, sansürleme ve propaganda üretme', 'Sinyal yükseltme, frekans modülasyonu ve parazit kesme', 'Kamusal mesafe koyma, alansallık işaretleme ve haptik temas'], 'Osgood-Schramm dairesel modelinde her katılımcı gelen mesajı çözer (decoder), anlamlandırır (interpreter) ve yeni mesaj üretir (encoder).'),
  ('İletişim çalışmalarında doğrusal (aktarım) modeller ile yapılandırmacı / ritüel iletişim modelleri karşılaştırıldığında, James Carey\'nin "ritüel iletişim" yaklaşımı neyi ön plana çıkarır?', 'İletişimin yalnızca mekanda bilgi taşımak değil, ortak inançları paylaşarak topluluğu zaman içinde bir arada tutmak olduğunu', ['İletişimin tek amacının kaynaktan alıcıya en kısa sürede emir ulaştırıp davranış değişikliği yaratmak olduğunu', 'Geri bildirim ve empati süreçlerinin bilimsel iletişim araştırmalarından çıkarılması gerektiğini', 'Sözsüz iletişimin yalnızca ilkel toplumlarda görülen arkaik bir kalıntı olduğunu'], 'James Carey\'e göre aktarım görüşü bilgiyi mesafeler arası yaymaya odaklanırken, ritüel görüş ortak değerlerin törensel paylaşımı ve toplumsal bütünleşmeye odaklanır.'),
  ('Lazarsfeld ve Katz\'a göre bir "kanaat önderi"nin (opinion leader) toplumsal konumu hakkında aşağıdaki yargılardan hangisi doğrudur?', 'Yalnızca toplumun en üst elit tabakasında değil, her sosyoekonomik katmanın kendi içinde ve konuya göre değişen biçimde bulunur', ['Her zaman resmi bir devlet makamına veya ulusal bir televizyon kanalının sahipliğine sahip olmak zorundadır', 'Moda konusunda kanaat önderi olan bir kişi zorunlu olarak dış politika ve tıp konularında da kanaat önderidir', 'Kanaat önderleri medyayı hiç takip etmeyen, yalnızca geleneksel söylentilerle hareket eden kapalı kişilerdir'], 'Kanaat önderliği yatay olarak her toplumsal sınıfta görülür ve genellikle polimorfik değil monomorfiktir (belirli bir uzmanlık/ilgi alanıyla sınırlıdır).'),
  ('Kullanımlar ve doyumlar literatüründe Donald Horton ve Richard Wohl tarafından ortaya atılan "parasosyal etkileşim" kavramı neyi ifade eder?', 'İzleyicinin ekran karşısındaki sunucu, oyuncu veya medya figürüyle sanki yüz yüze tanıdığı gerçek bir arkadaşıymış gibi tek taraflı duygusal bağ kurmasını', ['İki farklı televizyon kanalının aynı saatte ortak canlı yayın yaparak reklam gelirlerini paylaşmasını', 'Kanaat önderlerinin mahalle kahvehanelerinde seçmenlerle yüz yüze siyasi tartışma yürütmesini', 'Gazete okurlarının editöre mektup yazarak basım hatalarını düzeltmesini'], 'Parasosyal etkileşim, izleyicinin medya personasıyla geliştirdiği yanılsamalı samimiyet ve arkadaşlık hissidir; yalnızlık giderme doyumunda sık görülür.'),
  ('Eleştirel iletişim kuramcılarının "Kullanımlar ve Doyumlar" yaklaşımına yönelttikleri en temel metodolojik ve kuramsal eleştiri aşağıdakilerden hangisidir?', 'Medya sahipliği yapısını, ideolojik hegemonya gücünü ve sunulan seçeneklerin sınırlılığını göz ardı ederek izleyici özgürlüğünü aşırı abartması', ['İzleyicilerin medya tercihlerini araştırırken anket veya mülakat yöntemini kullanmayı tamamen yasaklaması', 'İnsanların eğlence içeriklerini izleyebileceğini reddedip yalnızca haber bültenlerini incelemesi', 'Kitle iletişim araçlarının bireylerde her zaman şiddet ve suç davranışı yarattığını iddia etmesi'], 'Eleştirel ekole göre izleyici yalnızca medyanın önüne koyduğu "standartlaştırılmış menü" içinden seçim yapabildiği için kuram toplumsal güç ilişkilerini ihmal eder.'),
  ('Frankfurt Okulu\'nun "Kültür Endüstrisi" tezine göre, boş zaman (leisure time) ile çalışma zamanı arasındaki ilişki kapitalist toplumda nasıl biçimlenir?', 'Boş zaman eğlenceleri çalışma hayatının bir uzantısına dönüşür; bireyi eleştirel düşünmekten uzaklaştırıp ertesi günkü iş gücüne yeniden uyumlu hale getirir', ['Boş zaman etkinlikleri işçilerin sistem karşıtı devrimci bilinç kazanmasını sağlayan en özerk direniş alanını oluşturur', 'Çalışma saatleri tamamen ortadan kalkarak toplumun tüm zamanı yüksek felsefi ve sanatsal üretimle geçer', 'Kültür endüstrisi bireyleri sürekli rahatsız edici avangart eserlerle yüzleştirerek zihinsel yorgunluğa sürükler'], 'Adorno ve Horkheimer\'a göre kültür endüstrisinde eğlence, bireyin düşünme yetisini uyuşturarak mevcut düzene rıza göstermesini (konformizmi) sağlar.'),
  ('Walter Benjamin\'in "Tekniğin Olanaklarıyla Yeniden Üretilebildiği Çağda Sanat Yapıtı" makalesinde fotoğraf ve sinema gibi kitle çoğaltım araçlarıyla sanat eserinin yitirdiğini söylediği "aura" (hale/biriciklik) ne anlama gelir?', 'Sanat yapıtının belirli bir zaman ve mekandaki özgün, tekil varlığı ile tarihsel tanıklığından doğan mesafeli saygınlığı', ['Sinema perdesinin arkasında kullanılan yüksek güçlü projeksiyon lambalarının yaydığı fiziksel ışık şiddeti', 'Ünlü oyuncuların magazin gazetelerinde yer alan özel hayat dedikodularının yarattığı ticari reklam değeri', 'Radyo vericilerinin elektromanyetik dalgaları atmosferin iyonosfer tabakasına yansıtma kapasitesi'], 'Benjamin\'e göre mekanik yeniden üretim (baskı, fotoğraf, film), sanat eserinin "şimdi ve buradalığını" yani biricik aurasını aşındırarak eseri kitlelere yaklaştırır.'),
  ('Marshall McLuhan\'ın teknolojik belirlenimci iletişim tarihinde insanlık tarihini ayırdığı dört ana dönem kronolojik sırasıyla aşağıdakilerin hangisinde doğru verilmiştir?', 'Kabile çağı (sözlü kültür) - Edebiyat/alfabe çağı - Basım çağı (Gutenberg Galaksisi) - Elektronik çağ', ['Taş devri - Tunç devri - Buharlı makine devri - Nükleer enerji devri', 'Feodal dönem - Merkantilist dönem - Sanayi kapitalizmi - Finans kapitalizmi', 'Mitolojik dönem - Teolojik dönem - Metafizik dönem - Pozitivist dönem'], 'McLuhan iletişim teknolojilerine göre tarihi; işitsel kabile çağı, fonetik alfabeyle başlayan yazı çağı, matbaayla kurulan Gutenberg Galaksisi ve işitsel-dokunsal kabileleşmeyi geri getiren elektronik çağ olarak böler.'),
  ('McLuhan\'ın "Küresel Köy" (Global Village) kavramı elektronik iletişim araçlarının dünya toplumları üzerinde nasıl bir dönüşüm yarattığını açıklar?', 'Elektronik medyanın zaman ve mekan mesafelerini ortadan kaldırarak dünyayı, herkesin birbirinin olaylarından anında haberdar olduğu işitsel-bütüncül bir kabile yapısına dönüştürdüğünü', ['Dünyadaki tüm büyük metropollerin yıkılarak insanların yeniden tarım ve hayvancılıkla uğraşan kırsal köylere göç ettiğini', 'Uluslararası ticaret anlaşmaları sayesinde tüm ülkelerin tek bir ortak para birimi ve tek bir anadili benimsediğini', 'Matbaanın icadıyla birlikte bireyciliğin ve ulus-devlet sınırlarının sonsuza dek aşılmaz hale geldiğini'], 'Elektronik medya, matbaanın yarattığı bireyci ve doğrusal parçalanmayı tersine çevirerek anlık, eşzamanlı ve kolektif bir küresel farkındalık ("küresel köy") üretir.'),
  ('Lazarsfeld ve Merton\'a göre kitle iletişim araçlarının kişi, kurum veya toplumsal hareketlere medyada yer vererek onlara prestij ve meşruiyet sağlaması hangi kavramla adlandırılır?', 'Statü kazandırma (status conferral) işlevi', ['İki aşamalı filtreleme işlevi', 'Bilişsel uyumsuzluk azaltma işlevi', 'Paralinguistik vurgulama işlevi'], 'Medyanın bir kişiyi veya konuyu gündeme taşıması, "önemli olmasaydı medyada yer almazdı" algısı yaratarak ona toplumsal statü bahşeder.'),
  ('Philip Palmgreen ve Jay Rayburn tarafından kullanımlar ve doyumlar kuramına eklenen "beklenti-değer" (expectancy-value) modeli, medya kullanım davranışını hangi iki değişkenin karşılaştırılmasıyla açıklar?', 'Aranan doyumlar (beklentiler) ile elde edilen gerçek doyumların karşılaştırılması', ['Yayın kuruluşunun kar oranı ile reklamverenin vergi matrahının karşılaştırılması', 'Kaynağın konuşma hızı ile alıcının okuma hızının karşılaştırılması', 'Sıcak araçların çözünürlüğü ile soğuk araçların ekran boyutunun karşılaştırılması'], 'Palmgreen ve Rayburn, izleyicinin medyadan "beklediği doyum" (gratifications sought) ile kullanım sonunda "elde ettiği doyum" (gratifications obtained) arasındaki farkın sonraki medya seçimini belirlediğini göstermiştir.'),
  ('Walter Benjamin ile Theodor Adorno arasındaki ünlü estetik tartışmasında, sinema gibi kitle iletişim araçlarının politik potansiyeli konusunda iki düşünür nasıl ayrışmıştır?', 'Benjamin sinemanın kitlelerde kolektif ve özgürleştirici bir algı yaratabileceğine iyimser yaklaşırken, Adorno kültür endüstrisinin bilinci tamamen şeyleştirip pasifleştirdiğini savunmuştur', ['Adorno Hollywood filmlerinin işçi sınıfını devrime hazırladığını savunurken, Benjamin tüm kameraların yasaklanmasını istemiştir', 'Her iki düşünür de ticari radyo reklamlarının yüksek klasik müzikten daha üstün bir sanat formu olduğunda uzlaşmıştır', 'Benjamin yalnızca yazılı basını desteklerken, Adorno televizyon dizilerinin empatiyi geliştirdiğini öne sürmüştür'], 'Benjamin auranın yitimiyle sanatın ritüelden politikaya açılma imkanını görürken, Adorno bu mekanik üretimin tekelci kapitalizm elinde kitle aldatmacasına dönüştüğünü belirtmiştir.'),
  ('Marshall McLuhan ve oğlu Eric McLuhan tarafından geliştirilen "Medya Dörtlüsü" (Tetrad of Media Effects) modelinde, yeni bir iletişim aracının etkilerini sorgulamak için sorulan dört temel soru hangileridir?', 'Neyi güçlendirir, neyi eskitir (işlevsizleştirir), geçmişten neyi geri getirir ve aşırı uç noktaya ulaştığında neye dönüşür?', ['Kim üretir, kaça satar, hangi ülkede yasaklanır ve kaç yıl garanti süresi vardır?', 'Kaynağı kimdir, kanalı nedir, gürültüsü ne kadardır ve geri bildirimi kaç saniyedir?', 'Bilişsel doyumu nedir, duygusal doyumu nedir, sosyal doyumu nedir ve kaçış doyumu nedir?'], 'McLuhan\'ın medya yasaları (tetrad); artırma (enhance), eskitme (obsolesce), geri kazanma (retrieve) ve tersine dönme (reverse) süreçlerinden oluşur.'),
  ('Alan Rubin\'in kullanımlar ve doyumlar araştırmalarında ortaya koyduğu "araçsal (instrumental) medya kullanımı" ile "ritüelistik (alışkanlığa dayalı) medya kullanımı" arasındaki fark nedir?', 'Araçsal kullanımda birey belirli bir bilgi veya içerik hedefiyle seçici davranırken, ritüelistik kullanımda vakit geçirmek için alışkanlıkla aracın kendisine yönelir', ['Araçsal kullanım yalnızca sinemada görülürken, ritüelistik kullanım yalnızca telgrafta görülür', 'Araçsal kullanımda izleyici tamamen pasifken, ritüelistik kullanımda izleyici bilimsel makale yazar', 'Araçsal kullanım sesli medyayı, ritüelistik kullanım ise yalnızca sessiz pandomim sanatını kapsar'], 'Haberin içeriğini öğrenmek için özel bir programı açmak araçsal; eve gelince sırf ses olsun veya alışkanlıktan televizyonu açık tutmak ritüelistik kullanımdır.'),
  ('1940\'lı yıllarda ABD\'de Paul Lazarsfeld ile Theodor W. Adorno\'yu "Princeton Radyo Projesi"nde bir araya getiren ancak yollarının ayrılmasına neden olan temel yöntemsel gerilim literatürde nasıl adlandırılır?', 'Yönetsel (idari/ampirik) araştırmalar ile eleştirel kuram arasındaki çatışma', ['Sözlü kültür araştırmaları ile arkeolojik kazı yöntemleri arasındaki çatışma', 'Nörobiyolojik deneyler ile dilbilimsel sentaks analizleri arasındaki çatışma', 'Kırsal sosyoloji ile kentsel mimari planlama arasındaki çatışma'], 'Lazarsfeld ölçülebilir kısa vadeli etkileri inceleyen "yönetsel araştırma"yı (administrative research), Adorno ise kapitalist sistemin bütüncül sorgulamasını yapan "eleştirel kuram"ı temsil etmiştir.'),
  ('Raymond Williams\'ın "Televizyon: Teknoloji ve Kültürel Biçim" adlı eserinde Marshall McLuhan\'ın teknolojik belirlenimciliğine getirdiği temel eleştiri nedir?', 'Teknolojinin toplumdan bağımsız özerk bir güç olmadığını; belirli toplumsal, ekonomik ve politik niyetlerin ürünü olarak geliştirilip şekillendirildiğini vurgulaması', ['Televizyonun insanlık tarihinde hiçbir kültürel etkisi olmadığını ve tamamen önemsiz bir ev eşyası olduğunu savunması', 'İletişim araçlarının yalnızca biyolojik evrim yasalarıyla kendiliğinden ortaya çıktığını ileri sürmesi', 'Yazılı basının televizyondan sonra icat edildiğini iddia etmesi'], 'Williams\'a göre teknoloji gökten zembille inip toplumu tek başına belirlemez; toplumsal ihtiyaçlar, iktidar ilişkileri ve kurumsal yatırımlar teknolojinin biçimini tayin eder.'),
  ('Stuart Hall\'un "Kodlama / Kod Açma" (Encoding / Decoding) modeli, hem Frankfurt Okulu\'nun "mutlak pasif izleyici" görüşünü hem de Kullanımlar ve Doyumlar\'ın "bütünüyle özgür bireysel izleyici" görüşünü nasıl aşmıştır?', 'Medya metinlerinin egemen ideolojiyle kodlandığını kabul etmekle birlikte, izleyicinin toplumsal konumuna göre egemen, müzakereci veya muhalif okuma yapabileceğini göstererek', ['İzleyicilerin medya mesajlarını anlamasının dilbilimsel olarak tamamen imkansız olduğunu savunarak', 'Tüm televizyon izleyicilerinin her haberi yüzde yüz aynı şekilde yorumladığını istatistiksel olarak kanıtlayarak', 'Medya kuruluşlarının hiçbir ideolojik çerçeve kullanmadan yalnızca ham kamera görüntüsü yayınladığını belirterek'], 'Hall\'a göre metin tamamen açık değildir (tercih edilen anlam vardır), ancak izleyici de kültür endüstrisinin kuklası değildir; sınıfsal/kültürel konumuna göre muhalif kod açımı yapabilir.'),
  ('Shannon-Weaver modelinde bir mesajın "enformasyon değeri" ile o mesajın "tahmin edilebilirliği" arasında nasıl bir matematiksel ilişki vardır?', 'Mesajın tahmin edilebilirliği azaldıkça (sürpriz/seçenek olasılığı arttıkça) taşıdığı enformasyon miktarı artar', ['Mesaj ne kadar bilindik ve tekrarlanan bir klişeyse taşıdığı enformasyon miktarı o kadar yüksektir', 'Enformasyon miktarı mesajın olasılığıyla değil, yalnızca harflerin kağıt üzerindeki punto büyüklüğüyle ölçülür', 'Tahmin edilebilirliği yüzde yüz olan bir mesaj sonsuz miktarda yeni enformasyon taşır'], 'Shannon\'ın enformasyon kuramında enformasyon belirsizliği azaltan şeydir; zaten kesin bilinen (olasılığı 1 olan) bir olayın haber değeri/enformasyonu sıfırdır.'),
  ('Harold Lasswell\'in 1948\'de kitle iletişiminin toplumsal işlevlerini tanımladığı klasik üçlü sınıflandırmasına, daha sonra Charles Wright tarafından eklenen dördüncü işlev aşağıdakilerden hangisidir?', 'Eğlendirme (entertainment)', ['Çevrenin gözetimi (haber verme)', 'Toplumsal kesimler arasında bağ kurma (yorumlama)', 'Kültürel mirasın kuşaktan kuşağa aktarımı (toplumsallaştırma)'], 'Lasswell\'in üç işlevi gözetim, bağ kurma/korele etme ve kültürel aktarımdır; Charles Wright buna dördüncü temel işlev olarak "eğlendirme"yi eklemiştir.'),
  ('İletişim kuramlarının tarihsel gelişimi bütüncül olarak değerlendirildiğinde; "Güçlü Etkiler (1920-1940) -> Sınırlı Etkiler (1940-1960) -> Yeniden Güçlü / Uzun Vadeli Bilişsel Etkiler (1970 sonrası)" sarmalında Lazarsfeld ve Adorno hangi konumlarda yer alır?', 'Lazarsfeld ampirik saha araştırmalarıyla "Sınırlı Etkiler" dönemini başlatırken, Adorno kültür endüstrisi eleştirisiyle medyanın bütüncül ideolojik gücünü vurgulamayı sürdürmüştür', ['Lazarsfeld medyanın insanları anında hipnotize ettiğini savunurken, Adorno televizyonun hiçbir toplumsal etkisi olmadığını ileri sürmüştür', 'Her iki kuramcı da kitle iletişim araçlarının yalnızca olumlu demokratik katılım ürettiğini savunan işlevselci ekolde yer almıştır', 'Adorno "Kullanımlar ve Doyumlar" kuramını kurarken, Lazarsfeld "Gutenberg Galaksisi" kavramını ortaya atmıştır'], 'Ana akım Amerikan sosyolojisinde Lazarsfeld sınırlı etkiler paradigmasının kurucusu olmuş; Frankfurt Okulu\'ndan Adorno ise medyanın uzun erimli bilinç endüstrisi gücüne dikkat çekmiştir.'),
];
